  (id, grade, subject, topic, sort_order, prompt, answer, source_file, is_active)
values
  ('P4-SCI-Q001', 'P4', 'Science', 'Plant Life', 1, 'What is a flowering plant?', 'A flowering plant is a plant that produces flowers.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q002', 'P4', 'Science', 'Plant Life', 2, 'Give two examples of flowering plants.', 'Examples include maize, beans, hibiscus and mango.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q003', 'P4', 'Science', 'Plant Life', 3, 'Why are flowers important to flowering plants?', 'Flowers help flowering plants to reproduce by forming seeds, often after pollination and fertilisation.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q004', 'P4', 'Science', 'Plant Life', 4, 'Name one flowering plant commonly grown in Uganda.', 'Examples include maize, beans, hibiscus or mango.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q005', 'P4', 'Science', 'Plant Life', 5, 'Name the main parts of a flower.', 'The main parts are sepals, petals, stamens and the carpel (pistil).', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q006', 'P4', 'Science', 'Plant Life', 6, 'Which part of a flower protects it before it opens?', 'The sepals protect the flower when it is still a bud.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q007', 'P4', 'Science', 'Plant Life', 7, 'What is the function of the petals?', 'Petals attract pollinators such as insects.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q008', 'P4', 'Science', 'Plant Life', 8, 'Which flower part contains the ovules?', 'The ovules are found in the ovary, which is part of the carpel.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q009', 'P4', 'Science', 'Plant Life', 9, 'What are sepals?', 'Sepals are the small, usually green parts that surround and protect a flower bud.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q010', 'P4', 'Science', 'Plant Life', 10, 'What is the function of sepals?', 'They protect the flower while it is still a bud.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q011', 'P4', 'Science', 'Plant Life', 11, 'How do sepals help a young flower?', 'They cover and protect the young flower from damage.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q012', 'P4', 'Science', 'Plant Life', 12, 'What may happen if the sepals are damaged before a flower opens?', 'The young flower may be damaged and may fail to develop normally.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q013', 'P4', 'Science', 'Plant Life', 13, 'What are petals?', 'Petals are the parts of a flower, often coloured, found inside the sepals.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q014', 'P4', 'Science', 'Plant Life', 14, 'Give two functions of petals.', 'They attract pollinators and help protect the reproductive parts of the flower.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q015', 'P4', 'Science', 'Plant Life', 15, 'Why are many petals brightly coloured?', 'Bright colours attract insects and other pollinators.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q016', 'P4', 'Science', 'Plant Life', 16, 'How can petals help in pollination?', 'They attract pollinators, which may carry pollen from one flower to another.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q017', 'P4', 'Science', 'Plant Life', 17, 'What are stamens?', 'Stamens are the male reproductive parts of a flower.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q018', 'P4', 'Science', 'Plant Life', 18, 'Name the two main parts of a stamen.', 'The anther and the filament.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q019', 'P4', 'Science', 'Plant Life', 19, 'What is produced in the anther?', 'Pollen grains are produced in the anther.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q020', 'P4', 'Science', 'Plant Life', 20, 'Why are stamens important in reproduction?', 'They produce pollen needed for reproduction.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q021', 'P4', 'Science', 'Plant Life', 21, 'What is a carpel?', 'A carpel is the female reproductive part of a flower.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q022', 'P4', 'Science', 'Plant Life', 22, 'Name the main parts of a carpel.', 'The stigma, style and ovary.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q023', 'P4', 'Science', 'Plant Life', 23, 'What is the function of the stigma?', 'The stigma receives pollen grains.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q024', 'P4', 'Science', 'Plant Life', 24, 'What happens to the ovules after fertilisation?', 'After fertilisation, the ovules develop into seeds.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q025', 'P4', 'Science', 'Plant Life', 25, 'What is pollination?', 'Pollination is the transfer of pollen grains from the anther to the stigma of a flower.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q026', 'P4', 'Science', 'Plant Life', 26, 'Name two agents of pollination.', 'Examples are insects and wind.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q027', 'P4', 'Science', 'Plant Life', 27, 'What is fertilisation in flowering plants?', 'Fertilisation is the joining of the male cell from pollen with the female cell in the ovule.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q028', 'P4', 'Science', 'Plant Life', 28, 'How is pollination different from fertilisation?', 'Pollination is the transfer of pollen to the stigma; fertilisation is the joining of the male and female cells.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q029', 'P4', 'Science', 'Plant Life', 29, 'What is a seed?', 'A seed is a part formed from a fertilised ovule and can grow into a new plant.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q030', 'P4', 'Science', 'Plant Life', 30, 'Where are seeds formed in a flowering plant?', 'Seeds are formed inside the ovary, which usually develops into a fruit.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q031', 'P4', 'Science', 'Plant Life', 31, 'Why are seeds important to plants?', 'Seeds grow into new plants and help plants reproduce.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q032', 'P4', 'Science', 'Plant Life', 32, 'Give four examples of seeds used as food.', 'Beans, maize, peas and groundnuts.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q033', 'P4', 'Science', 'Plant Life', 33, 'What is germination?', 'Germination is the process by which a seed begins to grow into a seedling.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q034', 'P4', 'Science', 'Plant Life', 34, 'Name three conditions needed for seed germination.', 'Water, air (oxygen) and suitable warmth.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q035', 'P4', 'Science', 'Plant Life', 35, 'Why does a seed need water during germination?', 'Water softens the seed coat and helps the seed begin its growth processes.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q036', 'P4', 'Science', 'Plant Life', 36, 'What happens to a seedling after germination?', 'The seedling develops roots, a shoot and leaves as it grows.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q037', 'P4', 'Science', 'Plant Life', 37, 'Mention five uses of plants to people.', 'Plants provide food, medicine, timber, firewood and materials for making things.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q038', 'P4', 'Science', 'Plant Life', 38, 'How do plants provide food?', 'People eat plant parts such as roots, stems, leaves, fruits and seeds.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q039', 'P4', 'Science', 'Plant Life', 39, 'How do plants provide materials for building or making things?', 'Plants provide timber, poles, fibres and materials used to make paper, baskets and furniture.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q040', 'P4', 'Science', 'Plant Life', 40, 'Why should useful plants be protected?', 'Useful plants provide food and other materials, protect the environment and support people''s livelihoods.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q041', 'P4', 'Science', 'Growing Crops', 41, 'What is an annual crop?', 'An annual crop is a crop that completes its life cycle within one year or one growing season.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q042', 'P4', 'Science', 'Growing Crops', 42, 'Give four examples of common annual crops.', 'Maize, beans, rice and sorghum.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q043', 'P4', 'Science', 'Growing Crops', 43, 'Why are maize and beans called annual crops?', 'They grow, produce seeds and complete their life cycle within one growing season.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q044', 'P4', 'Science', 'Growing Crops', 44, 'Name two annual crops commonly grown in Uganda.', 'Maize and beans.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q045', 'P4', 'Science', 'Growing Crops', 45, 'Name the main requirements for growing maize.', 'Suitable soil, water, sunlight, air, healthy seeds and proper care.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q046', 'P4', 'Science', 'Growing Crops', 46, 'What are two uses of maize?', 'Maize is used as food for people and feed for animals.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q047', 'P4', 'Science', 'Growing Crops', 47, 'Why should maize be planted in fertile soil?', 'Fertile soil supplies nutrients needed for healthy growth and good yields.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q048', 'P4', 'Science', 'Growing Crops', 48, 'Mention two problems that can reduce maize yield.', 'Pests and diseases; drought or poor soil.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q049', 'P4', 'Science', 'Growing Crops', 49, 'What conditions are needed for growing beans?', 'Suitable soil, water, warmth, sunlight and healthy seeds.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q050', 'P4', 'Science', 'Growing Crops', 50, 'Mention three uses of beans.', 'Beans are eaten as food, sold for income and used to improve soil fertility when properly managed.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q051', 'P4', 'Science', 'Growing Crops', 51, 'Why should beans be protected from pests?', 'Pests damage the plants and seeds and can reduce the harvest.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q052', 'P4', 'Science', 'Growing Crops', 52, 'How can a farmer improve bean production?', 'Use healthy seeds, prepare the land well, plant at the right time, weed and control pests and diseases.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q053', 'P4', 'Science', 'Growing Crops', 53, 'What is sorghum?', 'Sorghum is a cereal crop grown for its grain.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q054', 'P4', 'Science', 'Growing Crops', 54, 'Mention two uses of sorghum.', 'It is used as food and animal feed; some varieties are used to make drinks.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q055', 'P4', 'Science', 'Growing Crops', 55, 'Why can sorghum be important in areas with less rainfall?', 'It can tolerate drier conditions better than some other cereal crops.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q056', 'P4', 'Science', 'Growing Crops', 56, 'Name one product made from sorghum.', 'Flour or porridge can be made from sorghum grain.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q057', 'P4', 'Science', 'Growing Crops', 57, 'Name five garden tools.', 'Hoe, rake, panga, spade and watering can.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q058', 'P4', 'Science', 'Growing Crops', 58, 'What is a hoe used for?', 'A hoe is used for digging, making planting holes and weeding.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q059', 'P4', 'Science', 'Growing Crops', 59, 'What is a rake used for?', 'A rake is used for collecting rubbish and levelling soil.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q060', 'P4', 'Science', 'Growing Crops', 60, 'Why should garden tools be cleaned and stored safely?', 'Cleaning and safe storage prevent rust, damage and accidents and help tools last longer.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q061', 'P4', 'Science', 'Growing Crops', 61, 'Mention the main steps followed when growing an annual crop.', 'Clear the land, prepare the soil, select and plant seeds, water when needed, weed, control pests and diseases, and harvest at the right time.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q062', 'P4', 'Science', 'Growing Crops', 62, 'Why is land prepared before planting?', 'Land is prepared to loosen the soil, remove weeds and make planting easier.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q063', 'P4', 'Science', 'Growing Crops', 63, 'Why is weeding important?', 'Weeding reduces competition for water, light, space and nutrients.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q064', 'P4', 'Science', 'Growing Crops', 64, 'Why should crops be harvested at the right time?', 'Harvesting at the right time helps prevent losses and gives good-quality produce.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q065', 'P4', 'Science', 'Growing Crops', 65, 'What is a crop disease?', 'A crop disease is a condition that harms a crop and affects its normal growth.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q066', 'P4', 'Science', 'Growing Crops', 66, 'Mention two signs of disease in crops.', 'Yellowing leaves, spots on leaves, wilting or rotting.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q067', 'P4', 'Science', 'Growing Crops', 67, 'How can crop diseases reduce food production?', 'Diseases weaken or kill plants and reduce the amount and quality of produce.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q068', 'P4', 'Science', 'Growing Crops', 68, 'Give two ways of controlling crop diseases.', 'Use healthy planting materials and resistant varieties; remove infected plants and seek appropriate control advice.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q069', 'P4', 'Science', 'Growing Crops', 69, 'What is a crop pest?', 'A crop pest is an organism that damages crops.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q070', 'P4', 'Science', 'Growing Crops', 70, 'Give four examples of crop pests.', 'Locusts, aphids, caterpillars and weevils.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q071', 'P4', 'Science', 'Growing Crops', 71, 'How do pests damage crops?', 'They may eat leaves, stems, roots, flowers, fruits or seeds.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q072', 'P4', 'Science', 'Growing Crops', 72, 'Mention two ways of controlling crop pests.', 'Remove pests by hand where safe and suitable; use traps or recommended pest-control methods.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q073', 'P4', 'Science', 'Growing Crops', 73, 'Why should pests and diseases be controlled?', 'To protect crops and improve the quantity and quality of the harvest.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q074', 'P4', 'Science', 'Growing Crops', 74, 'Mention safe methods of controlling crop pests.', 'Use hand-picking, traps, crop rotation, field sanitation and only approved chemicals according to instructions.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q075', 'P4', 'Science', 'Growing Crops', 75, 'Why should farmers avoid careless use of chemicals?', 'Chemicals can poison people and animals, contaminate food and water, and harm useful organisms.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q076', 'P4', 'Science', 'Growing Crops', 76, 'How can good field hygiene reduce pests and diseases?', 'Removing weeds and crop remains can reduce places where pests and disease-causing organisms survive.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q077', 'P4', 'Science', 'Growing Crops', 77, 'Why should crops be watered when necessary?', 'Water helps seeds germinate and plants grow, especially during dry periods.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q078', 'P4', 'Science', 'Growing Crops', 78, 'Why is thinning sometimes done?', 'Thinning reduces overcrowding so that remaining plants get enough space, light, water and nutrients.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q079', 'P4', 'Science', 'Growing Crops', 79, 'Why should farmers remove weeds?', 'Weeds compete with crops for water, light, space and nutrients.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q080', 'P4', 'Science', 'Growing Crops', 80, 'How does proper crop care increase yield?', 'Healthy crops receive the conditions and care they need, so they are more likely to produce a good harvest.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q081', 'P4', 'Science', 'Weather Changes Around Us', 81, 'What is weather?', 'Weather is the condition of the atmosphere at a place over a short period.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q082', 'P4', 'Science', 'Weather Changes Around Us', 82, 'Mention four elements of weather.', 'Temperature, rainfall, wind and cloud cover.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q083', 'P4', 'Science', 'Weather Changes Around Us', 83, 'How can weather affect people''s daily activities?', 'Weather affects farming, clothing, travel, drying clothes and outdoor activities.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q084', 'P4', 'Science', 'Weather Changes Around Us', 84, 'Why is weather observation useful?', 'It helps people plan activities and farmers plan farm work.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q085', 'P4', 'Science', 'Weather Changes Around Us', 85, 'What is a change in weather?', 'A change in weather is a difference in conditions such as temperature, wind, cloud cover or rainfall.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q086', 'P4', 'Science', 'Weather Changes Around Us', 86, 'Mention signs that weather is changing.', 'Clouds gathering, wind increasing, temperature changing or rain beginning.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q087', 'P4', 'Science', 'Weather Changes Around Us', 87, 'Why can the weather change during the day?', 'Sunlight, wind, cloud cover and changes in the atmosphere can cause weather conditions to change.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q088', 'P4', 'Science', 'Weather Changes Around Us', 88, 'How can sudden weather changes affect farmers?', 'It may delay planting or harvesting, damage crops or cause flooding and soil erosion.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q089', 'P4', 'Science', 'Weather Changes Around Us', 89, 'What is the water cycle?', 'The water cycle is the continuous movement of water between the land, water bodies and the atmosphere.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q090', 'P4', 'Science', 'Weather Changes Around Us', 90, 'Name the main stages of the water cycle.', 'Evaporation, condensation and precipitation (rainfall).', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q091', 'P4', 'Science', 'Weather Changes Around Us', 91, 'What causes water to evaporate?', 'Heat from the Sun causes liquid water to change into water vapour.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q092', 'P4', 'Science', 'Weather Changes Around Us', 92, 'How does rainfall return water to the land?', 'Water droplets in clouds join and fall to the ground as rain.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q093', 'P4', 'Science', 'Weather Changes Around Us', 93, 'What is rainfall?', 'Rainfall is water falling from clouds to the ground in drops.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q094', 'P4', 'Science', 'Weather Changes Around Us', 94, 'Name two forms in which water may fall from clouds.', 'Rain and hail; in some places, snow also falls.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q095', 'P4', 'Science', 'Weather Changes Around Us', 95, 'How is rainfall measured?', 'Rainfall is measured using a rain gauge, usually in millimetres.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q096', 'P4', 'Science', 'Weather Changes Around Us', 96, 'Why is rainfall important to crops?', 'Rain supplies water needed for crop growth.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q097', 'P4', 'Science', 'Weather Changes Around Us', 97, 'What is a rain gauge?', 'A rain gauge is an instrument used to collect and measure rainfall.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q098', 'P4', 'Science', 'Weather Changes Around Us', 98, 'What does a rain gauge measure?', 'It measures the amount of rainfall.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q099', 'P4', 'Science', 'Weather Changes Around Us', 99, 'Where should a rain gauge be placed for useful readings?', 'Place it in an open area away from trees and buildings, where it can collect rain without obstruction.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q100', 'P4', 'Science', 'Weather Changes Around Us', 100, 'Why should the reading of a rain gauge be recorded regularly?', 'Regular records help show how much rain has fallen and how rainfall changes over time.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q101', 'P4', 'Science', 'Weather Changes Around Us', 101, 'What is a weather chart?', 'A weather chart is a table or chart used to record weather observations.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q102', 'P4', 'Science', 'Weather Changes Around Us', 102, 'What information can be shown on a simple weather chart?', 'It may show rainfall, temperature, wind, cloud cover and the daily weather condition.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q103', 'P4', 'Science', 'Weather Changes Around Us', 103, 'Why do learners record weather observations?', 'Records help learners compare weather conditions and identify changes over time.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q104', 'P4', 'Science', 'Weather Changes Around Us', 104, 'How can a weather chart help a farmer?', 'It helps a farmer plan planting, watering, spraying and harvesting.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q105', 'P4', 'Science', 'Weather Changes Around Us', 105, 'Why is sunshine important?', 'Sunshine provides light and warmth needed by plants and helps people dry clothes and crops.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q106', 'P4', 'Science', 'Weather Changes Around Us', 106, 'How can sunshine affect drying?', 'Sunshine provides heat that helps water evaporate and wet materials dry.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q107', 'P4', 'Science', 'Weather Changes Around Us', 107, 'How can too much sunshine affect crops?', 'Too much sunshine can dry the soil and cause plants to wilt.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q108', 'P4', 'Science', 'Weather Changes Around Us', 108, 'What instrument or method can be used to observe sunshine in simple weather work?', 'Observe and record the hours or periods of sunshine; a sunshine recorder may be used where available.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q109', 'P4', 'Science', 'Weather Changes Around Us', 109, 'What is wind?', 'Wind is moving air.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q110', 'P4', 'Science', 'Weather Changes Around Us', 110, 'How can wind be observed?', 'Observe the movement of leaves, flags or smoke, or use a wind vane to observe direction.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q111', 'P4', 'Science', 'Weather Changes Around Us', 111, 'Mention two effects of strong winds.', 'Strong winds can damage buildings and crops and blow down trees.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q112', 'P4', 'Science', 'Weather Changes Around Us', 112, 'Why can wind be useful to people?', 'Wind can help dry clothes and crops, move sailing boats and turn windmills or turbines.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q113', 'P4', 'Science', 'Weather Changes Around Us', 113, 'What are clouds?', 'Clouds are collections of tiny water droplets or ice crystals in the atmosphere.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q114', 'P4', 'Science', 'Weather Changes Around Us', 114, 'How can clouds give clues about coming rain?', 'Dark, thick clouds may indicate that rain is likely.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q115', 'P4', 'Science', 'Weather Changes Around Us', 115, 'Why do clouds form?', 'Clouds form when moist air cools and water vapour condenses into tiny droplets or ice crystals.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q116', 'P4', 'Science', 'Weather Changes Around Us', 116, 'Why are clouds important in the water cycle?', 'Clouds hold condensed water that may later fall as precipitation.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q117', 'P4', 'Science', 'Weather Changes Around Us', 117, 'How can people keep safe during heavy rain or strong winds?', 'Stay indoors or in a safe building, avoid flooded places and do not shelter under isolated trees during storms.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q118', 'P4', 'Science', 'Weather Changes Around Us', 118, 'What should a farmer consider before spraying crops?', 'The farmer should consider wind direction and speed, expected rain and the safety instructions for the product.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q119', 'P4', 'Science', 'Weather Changes Around Us', 119, 'Why should children avoid playing in flooded areas?', 'Floodwater may be deep, fast-moving or contaminated and can cause drowning or disease.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q120', 'P4', 'Science', 'Weather Changes Around Us', 120, 'How can weather information help people plan activities?', 'Weather information helps people choose suitable times for farming, travelling, drying produce and other activities.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q121', 'P4', 'Science', 'Personal Hygiene', 121, 'What is personal hygiene?', 'Personal hygiene is the practice of keeping the body and personal belongings clean to maintain health.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q122', 'P4', 'Science', 'Personal Hygiene', 122, 'Mention five personal hygiene practices.', 'Examples include bathing, brushing teeth, washing hands, trimming nails and wearing clean clothes.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q123', 'P4', 'Science', 'Personal Hygiene', 123, 'Why is personal hygiene important?', 'It helps prevent diseases, removes dirt and body odour, and keeps a person healthy.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q124', 'P4', 'Science', 'Personal Hygiene', 124, 'How can poor hygiene affect a learner?', 'A learner may get infections, feel uncomfortable, smell bad or be teased by others.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q125', 'P4', 'Science', 'Personal Hygiene', 125, 'How should a person keep the body clean?', 'Bathe regularly with clean water and soap, and wash the body properly.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q126', 'P4', 'Science', 'Personal Hygiene', 126, 'Why should the body be washed regularly?', 'Washing removes sweat, dirt and germs from the skin.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q127', 'P4', 'Science', 'Personal Hygiene', 127, 'Why should the hair be kept clean?', 'Clean hair helps prevent dirt, bad smell and some scalp problems.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q128', 'P4', 'Science', 'Personal Hygiene', 128, 'What can happen when the body is not kept clean?', 'The person may develop body odour, skin problems or infections.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q129', 'P4', 'Science', 'Personal Hygiene', 129, 'Why should we bathe regularly?', 'Regular bathing removes sweat, dirt and germs and helps keep the skin healthy.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q130', 'P4', 'Science', 'Personal Hygiene', 130, 'What can be used for bathing?', 'Clean water, soap, a washcloth or sponge, and a clean towel may be used.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q131', 'P4', 'Science', 'Personal Hygiene', 131, 'Why should a clean towel be used?', 'A clean towel helps avoid transferring dirt and germs back to the body.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q132', 'P4', 'Science', 'Personal Hygiene', 132, 'How does bathing help prevent body odour?', 'Bathing washes away sweat and bacteria that can cause body odour.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q133', 'P4', 'Science', 'Personal Hygiene', 133, 'Why should teeth be cleaned every day?', 'Cleaning teeth removes food particles and plaque and helps prevent tooth decay and bad breath.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q134', 'P4', 'Science', 'Personal Hygiene', 134, 'What should be used to clean teeth?', 'A toothbrush and toothpaste, or another safe recommended tooth-cleaning method, should be used.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q135', 'P4', 'Science', 'Personal Hygiene', 135, 'How can dirty teeth cause problems?', 'Dirty teeth can develop tooth decay, gum disease and bad breath.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q136', 'P4', 'Science', 'Personal Hygiene', 136, 'Why should sugary foods be taken in moderation?', 'Too much sugar encourages tooth decay and may contribute to poor health.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q137', 'P4', 'Science', 'Personal Hygiene', 137, 'When should hands be washed?', 'Wash hands before preparing or eating food, after using the toilet, after handling waste, and after touching dirty things or animals.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q138', 'P4', 'Science', 'Personal Hygiene', 138, 'Why should hands be washed before eating?', 'Handwashing removes germs that could enter the mouth with food.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q139', 'P4', 'Science', 'Personal Hygiene', 139, 'Why should hands be washed after using a toilet?', 'It removes germs from the hands and helps prevent the spread of intestinal diseases.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q140', 'P4', 'Science', 'Personal Hygiene', 140, 'How does handwashing help prevent disease?', 'It removes germs from the hands before they can enter the body or spread to other people and surfaces.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q141', 'P4', 'Science', 'Personal Hygiene', 141, 'Why should clothes be kept clean?', 'Clean clothes remove dirt and sweat, help prevent skin problems and make a person comfortable.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q142', 'P4', 'Science', 'Personal Hygiene', 142, 'How should dirty clothes be handled?', 'Keep dirty clothes separate from clean clothes and wash them with soap and clean water.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q143', 'P4', 'Science', 'Personal Hygiene', 143, 'Why should clothes be dried properly after washing?', 'Proper drying helps prevent dampness, unpleasant smells and the growth of some fungi.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q144', 'P4', 'Science', 'Personal Hygiene', 144, 'What problems may result from wearing dirty clothes?', 'They may cause body odour, skin irritation or infections and attract pests.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q145', 'P4', 'Science', 'Personal Hygiene', 145, 'Why should bedding be washed and aired?', 'Washing and airing bedding removes dirt, sweat and some germs and helps keep it fresh.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q146', 'P4', 'Science', 'Personal Hygiene', 146, 'Mention examples of bedding.', 'Examples are bedsheets, blankets, pillowcases, pillows and mattresses.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q147', 'P4', 'Science', 'Personal Hygiene', 147, 'How can dirty bedding affect health?', 'Dirty bedding may contribute to skin irritation, unpleasant smells and the spread of some infections or pests.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q148', 'P4', 'Science', 'Personal Hygiene', 148, 'Why is sunlight useful when airing bedding?', 'Sunlight helps dry bedding and may reduce some germs and dampness.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q149', 'P4', 'Science', 'Personal Hygiene', 149, 'Why should people avoid sharing personal items such as toothbrushes?', 'Sharing them can transfer germs, lice or other infections from one person to another.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q150', 'P4', 'Science', 'Personal Hygiene', 150, 'Name two personal items that should not be shared.', 'Examples are toothbrushes and towels. Combs and razors should also not be shared.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q151', 'P4', 'Science', 'Personal Hygiene', 151, 'How should personal items be stored?', 'Keep personal items clean, dry and in a clean, separate place.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q152', 'P4', 'Science', 'Personal Hygiene', 152, 'Why should combs and towels be kept clean?', 'They can collect dirt and germs and transfer them to the body or hair.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q153', 'P4', 'Science', 'Personal Hygiene', 153, 'How can poor hygiene spread disease?', 'Germs can pass through dirty hands, contaminated food or water, dirty clothing and unclean surroundings.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q154', 'P4', 'Science', 'Personal Hygiene', 154, 'Mention two diseases associated with poor hygiene.', 'Examples include diarrhoea and some skin infections. Poor hygiene can also help spread intestinal worms.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q155', 'P4', 'Science', 'Personal Hygiene', 155, 'How can good hygiene reduce disease?', 'Good hygiene removes or reduces germs and lowers the chance of infection.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q156', 'P4', 'Science', 'Personal Hygiene', 156, 'Why is cleanliness important at school?', 'It helps learners stay healthy, prevents the spread of disease and creates a pleasant place for learning.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q157', 'P4', 'Science', 'Personal Hygiene', 157, 'Describe a simple daily hygiene routine for a learner.', 'A learner can bathe, brush the teeth, wash hands with soap, wear clean clothes, trim nails and keep personal items clean.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q158', 'P4', 'Science', 'Personal Hygiene', 158, 'Why should nails be trimmed?', 'Short nails collect less dirt and are easier to clean, reducing the spread of germs.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q159', 'P4', 'Science', 'Personal Hygiene', 159, 'Why should shoes and socks be kept clean?', 'Clean shoes and socks help reduce bad smells and may prevent some foot problems.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P4-SCI-Q160', 'P4', 'Science', 'Personal Hygiene', 160, 'How can a learner encourage good hygiene at home?', 'A learner can practise good hygiene, explain its benefits, remind family members kindly and help keep shared areas clean.', 'P4-P6_Science_Questions_and_Answers_Progress_Q1-160.md', true),
  ('P5_SCI_T01-Q1', 'P5', 'Science', 'Keeping Poultry and Bees', 1, 'What is poultry? Name any five types.', 'Poultry are birds kept at home for meat, eggs and money. Any five of: chicken, turkeys, ducks, guinea fowls, geese, pigeons.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T01', true),
  ('P5_SCI_T01-Q2', 'P5', 'Science', 'Keeping Poultry and Bees', 2, 'Name any six external parts of a domestic fowl.', 'Any six of: comb, wattle, beak, eyes, feathers, wings, legs with scales, claws, tail, vent.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T01', true),
  ('P5_SCI_T01-Q3', 'P5', 'Science', 'Keeping Poultry and Bees', 3, 'Give three differences between a cock and a hen.', 'A cock has a big comb and wattles, bright feathers, long pointed tail feathers and spurs, and it crows; a hen has a smaller comb, a rounded body, lays eggs and broods.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T01', true),
  ('P5_SCI_T01-Q4', 'P5', 'Science', 'Keeping Poultry and Bees', 4, 'Name the four systems of keeping poultry and describe two.', 'Free range, deep litter, battery cage and fold. (Describe two, for example: in deep litter birds are kept in a house on a floor covered with coffee husks or wood shavings; in free range the birds move about freely and look for their own food.)', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T01', true),
  ('P5_SCI_T01-Q5', 'P5', 'Science', 'Keeping Poultry and Bees', 5, 'Name any three breeds of chicken and what each is kept for.', 'Any three: White Leghorn — eggs; broilers — meat; Rhode Island Red — meat and eggs; local kienyeji — meat, eggs and hardiness.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T01', true),
  ('P5_SCI_T01-Q6', 'P5', 'Science', 'Keeping Poultry and Bees', 6, 'Give any six ways of caring for poultry.', 'Any six of: provide a clean, dry, well-ventilated house; give clean water always; feed a balanced ration; vaccinate; deworm and dust against parasites; isolate sick birds; remove wet litter; protect from predators and thieves; keep records.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T01', true),
  ('P5_SCI_T01-Q7', 'P5', 'Science', 'Keeping Poultry and Bees', 7, 'Name any four poultry diseases and any three poultry parasites.', 'Diseases: Newcastle, coccidiosis, fowl typhoid, fowl pox, gumboro (any four). Parasites: lice, mites, fleas, ticks, worms (any three).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T01', true),
  ('P5_SCI_T01-Q8', 'P5', 'Science', 'Keeping Poultry and Bees', 8, 'Name the three types of bees in a colony and the work of each.', 'Queen — the only fertile female, lays all the eggs; drones — males that mate with the queen; workers — sterile females that collect nectar, make honey, build combs, feed the young, guard and clean the hive.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T01', true),
  ('P5_SCI_T01-Q9', 'P5', 'Science', 'Keeping Poultry and Bees', 9, 'Give two traditional and two modern types of beehives.', 'Traditional: log hives and pot or basket hives. Modern: the Kenya Top Bar hive and the Langstroth hive.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T01', true),
  ('P5_SCI_T01-Q10', 'P5', 'Science', 'Keeping Poultry and Bees', 10, 'Give any four things to consider when siting an apiary.', 'Any four of: a quiet, shady place; near water and flowering plants; away from homes, paths and animals; safe from thieves; protected from ants by greasing the wires.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T01', true),
  ('P5_SCI_T01-Q11', 'P5', 'Science', 'Keeping Poultry and Bees', 11, 'Give the steps followed when harvesting honey.', 'Harvest in the evening or early morning → wear protective clothing → light the smoker and calm the bees → open the hive quietly → cut only combs with sealed honey, leaving some for the bees → put the combs in clean containers → close the hive → strain the honey and store it in a cool, dry place.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T01', true),
  ('P5_SCI_T01-Q12', 'P5', 'Science', 'Keeping Poultry and Bees', 12, 'Why is protective clothing and a smoker used during harvesting?', 'Because bees sting to defend the hive. Protective clothing keeps the stings off the body, and the smoke calms the bees so they do not attack the harvester.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T01', true),
  ('P5_SCI_T01-Q13', 'P5', 'Science', 'Keeping Poultry and Bees', 13, 'Name any five products got from bees.', 'Any five of: honey, beeswax, propolis, royal jelly, bee venom, and pollination services.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T01', true),
  ('P5_SCI_T01-Q14', 'P5', 'Science', 'Keeping Poultry and Bees', 14, 'Give any five reasons why poultry and bee keeping are good businesses.', 'Any five of: they need little land and little capital; they give food and income; they create employment; droppings give manure; bees pollinate crops; the products sell easily; they can be run beside other work.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T01', true),
  ('P5_SCI_T01-Q15', 'P5', 'Science', 'Keeping Poultry and Bees', 15, 'Give any four records a poultry farmer should keep.', 'Any four of: numbers of birds bought and sold; eggs collected each day; feeds used and their cost; vaccinations and treatments given; deaths; income and expenses.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T01', true),
  ('P5_SCI_T02-Q1', 'P5', 'Science', 'Measurement', 16, 'Give the difference between mass and weight.', 'Mass is the amount of matter in an object and never changes; weight is the pull of gravity on the object and changes from place to place.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T02', true),
  ('P5_SCI_T02-Q2', 'P5', 'Science', 'Measurement', 17, 'Name the instrument and the unit used for measuring: mass, weight, volume of a liquid.', 'Mass — beam balance, in kilogrammes; weight — spring balance, in newtons; volume of a liquid — measuring cylinder or jug, in litres or millilitres.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T02', true),
  ('P5_SCI_T02-Q3', 'P5', 'Science', 'Measurement', 18, 'Give the difference between capacity and volume.', 'Capacity is how much a container can hold; volume is the space a substance occupies.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T02', true),
  ('P5_SCI_T02-Q4', 'P5', 'Science', 'Measurement', 19, 'Change: 3 kg to grammes; 2.5 litres to millilitres; 4,000 cm³ to litres.', '3 kg = 3,000 g; 2.5 litres = 2,500 ml; 4,000 cm³ = 4 litres.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T02', true),
  ('P5_SCI_T02-Q5', 'P5', 'Science', 'Measurement', 20, 'Find the volume of a box 8 cm long, 5 cm wide and 4 cm high.', '8 × 5 × 4 = 160 cm³', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T02', true),
  ('P5_SCI_T02-Q6', 'P5', 'Science', 'Measurement', 21, 'Why are standard measures better than the hand span or the calabash?', 'Because standard measures are the same everywhere and never change, while a hand span or calabash differs from person to person, so trade would be unfair and measurements could not be repeated.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T02', true),
  ('P5_SCI_T02-Q7', 'P5', 'Science', 'Measurement', 22, 'What makes an object float or sink?', 'An object floats if it is less dense than the liquid and sinks if it is more dense. Its shape also matters, because a shape that holds air pushes aside more water.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T02', true),
  ('P5_SCI_T02-Q8', 'P5', 'Science', 'Measurement', 23, 'Give three objects that float and three that sink in water.', 'Float: wood, cork, a plastic bottle with air (also ice, oil). Sink: a stone, a nail, a metal spoon (also sand, glass).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T02', true),
  ('P5_SCI_T02-Q9', 'P5', 'Science', 'Measurement', 24, 'Why does an iron sheet sink while a boat made of iron floats?', 'The flat sheet is denser than water so it sinks; the boat shape holds air and pushes aside much more water, so the boat as a whole is less dense than water and floats.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T02', true),
  ('P5_SCI_T02-Q10', 'P5', 'Science', 'Measurement', 25, 'Describe an experiment to show that an egg floats in salty water.', 'Put an egg in a glass of fresh water — it sinks. Add salt slowly, stirring, and keep watching. As more salt dissolves, the water becomes denser, and at some point the egg rises and floats. This shows that a liquid''s density affects floating.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T02', true),
  ('P5_SCI_T02-Q11', 'P5', 'Science', 'Measurement', 26, 'Describe the displacement method for finding the volume of a stone.', 'Pour water into a measuring cylinder and read the level. Lower the stone gently on a string until it is fully covered. Read the new level. Subtract the first reading from the second — the difference is the volume of the stone.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T02', true),
  ('P5_SCI_T02-Q12', 'P5', 'Science', 'Measurement', 27, 'A stone raises the water level in a cylinder from 30 cm³ to 75 cm³. Find its volume.', '75 − 30 = 45 cm³', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T02', true),
  ('P5_SCI_T02-Q13', 'P5', 'Science', 'Measurement', 28, 'Define density and give its formula and unit.', 'Density is the mass of a substance in a given volume. Density = mass ÷ volume, measured in g/cm³.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T02', true),
  ('P5_SCI_T02-Q14', 'P5', 'Science', 'Measurement', 29, 'An object of mass 240 g has a volume of 60 cm³. Find its density.', '240 ÷ 60 = 4 g/cm³', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T02', true),
  ('P5_SCI_T02-Q15', 'P5', 'Science', 'Measurement', 30, 'A block of density 2.5 g/cm³ has a volume of 40 cm³. Find its mass.', 'Mass = density × volume = 2.5 × 40 = 100 g', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T02', true),
  ('P5_SCI_T03-Q1', 'P5', 'Science', 'Components of the Environment — Soil', 31, 'What is soil? Give the two ways in which it is formed.', 'Soil is the loose top layer of the earth''s surface in which plants grow. It is formed by the weathering of rocks and the decomposition of dead plant and animal matter.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T03', true),
  ('P5_SCI_T03-Q2', 'P5', 'Science', 'Components of the Environment — Soil', 32, 'Name three kinds of weathering and give an example of each.', 'Physical — heat and cold cracking rocks; chemical — water and chemicals dissolving rocks; biological — plant roots and burrowing animals breaking rocks.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T03', true),
  ('P5_SCI_T03-Q3', 'P5', 'Science', 'Components of the Environment — Soil', 33, 'Name the three types of soil and give two properties of each.', 'Sandy — large particles, drains very fast, poor at holding water; clay — very small particles, sticky when wet and hard when dry, holds too much water; loam — a mixture with plenty of humus, holds enough water and drains well.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T03', true),
  ('P5_SCI_T03-Q4', 'P5', 'Science', 'Components of the Environment — Soil', 34, 'Which soil is best for farming, and why?', 'Loam, because it holds enough water but still drains well, contains air and plenty of humus, and is easy to work.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T03', true),
  ('P5_SCI_T03-Q5', 'P5', 'Science', 'Components of the Environment — Soil', 35, 'Which soil is used for making pots and bricks, and why?', 'Clay, because its very fine particles stick together when wet and become hard when dried or fired.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T03', true),
  ('P5_SCI_T03-Q6', 'P5', 'Science', 'Components of the Environment — Soil', 36, 'Name the layers of a soil profile from the top.', 'Top soil → sub soil → weathered rock → bedrock.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T03', true),
  ('P5_SCI_T03-Q7', 'P5', 'Science', 'Components of the Environment — Soil', 37, 'Name the five components of soil.', 'Mineral (rock) particles, air, water, humus and living things.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T03', true),
  ('P5_SCI_T03-Q8', 'P5', 'Science', 'Components of the Environment — Soil', 38, 'Describe an experiment to show that soil contains air.', 'Drop dry soil into a container of water. Bubbles rise to the surface, showing that air was trapped in the spaces between the soil particles.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T03', true),
  ('P5_SCI_T03-Q9', 'P5', 'Science', 'Components of the Environment — Soil', 39, 'Describe an experiment to show that soil contains water.', 'Put soil in a dry test tube and heat it gently. Drops of water appear on the cooler upper part of the tube, showing that the soil contained water.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T03', true),
  ('P5_SCI_T03-Q10', 'P5', 'Science', 'Components of the Environment — Soil', 40, 'Describe an experiment to show that soil contains humus.', 'Heat soil strongly in a tin or on a metal sheet. It gives off smoke and a burning smell and becomes lighter in colour, showing that the humus has burnt away.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T03', true),
  ('P5_SCI_T03-Q11', 'P5', 'Science', 'Components of the Environment — Soil', 41, 'Give any six importances of soil.', 'Any six of: it anchors plants and supplies water and mineral salts; it is used for farming; it is a home for soil animals; it is used for building bricks and roads; it is used for pottery; it holds and filters water; some soils contain minerals.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T03', true),
  ('P5_SCI_T03-Q12', 'P5', 'Science', 'Components of the Environment — Soil', 42, 'What is soil erosion? Name any four types.', 'Soil erosion is the carrying away of the top soil by water, wind or animals. Types: sheet, rill, gully, wind erosion and landslides (any four).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T03', true),
  ('P5_SCI_T03-Q13', 'P5', 'Science', 'Components of the Environment — Soil', 43, 'Give any five causes of soil erosion.', 'Any five of: cutting down trees; bush burning; overgrazing; farming on steep slopes; over-cultivation; poor road drainage; heavy rain falling on bare soil.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T03', true),
  ('P5_SCI_T03-Q14', 'P5', 'Science', 'Components of the Environment — Soil', 44, 'What is soil exhaustion, and what causes it?', 'Soil exhaustion is the loss of soil fertility. It is caused by growing the same crop again and again, over-cultivation, and failing to add manure or rest the land.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T03', true),
  ('P5_SCI_T03-Q15', 'P5', 'Science', 'Components of the Environment — Soil', 45, 'Give any eight methods of soil conservation.', 'Any eight of: mulching; terracing; contour ploughing; strip cropping; crop rotation; applying manure and compost; planting cover crops and trees; controlled grazing; fallowing; digging trenches and check dams.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T03', true),
  ('P5_SCI_T04-Q1', 'P5', 'Science', 'Immunisation', 46, 'What is immunity? Name its two types.', 'Immunity is the ability of the body to fight and resist disease. Its two types are natural and acquired (artificial) immunity.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T04', true),
  ('P5_SCI_T04-Q2', 'P5', 'Science', 'Immunisation', 47, 'Give three examples of natural immunity.', 'Any three of: the skin, tears, saliva and stomach acid; white blood cells; antibodies a baby gets from the mother and from breast milk; immunity left after recovering from a disease.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T04', true),
  ('P5_SCI_T04-Q3', 'P5', 'Science', 'Immunisation', 48, 'What is immunisation, and what is a vaccine?', 'Immunisation is giving a person a vaccine so that the body can make antibodies and resist a disease. A vaccine is a medicine, usually made from weakened or killed germs, given to protect the body.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T04', true),
  ('P5_SCI_T04-Q4', 'P5', 'Science', 'Immunisation', 49, 'Name any six immunisable childhood diseases.', 'Any six of: tuberculosis, polio, diphtheria, whooping cough, tetanus, measles, hepatitis B, Haemophilus influenzae type b (also pneumonia and rotavirus today).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T04', true),
  ('P5_SCI_T04-Q5', 'P5', 'Science', 'Immunisation', 50, 'Which vaccine protects against tuberculosis, and when is it given?', 'BCG, given at birth, on the right upper arm.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T04', true),
  ('P5_SCI_T04-Q6', 'P5', 'Science', 'Immunisation', 51, 'Which five diseases are covered by the pentavalent vaccine?', 'Diphtheria, whooping cough, tetanus, hepatitis B and Haemophilus influenzae type b (Hib).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T04', true),
  ('P5_SCI_T04-Q7', 'P5', 'Science', 'Immunisation', 52, 'At what ages are polio and pentavalent vaccines given?', 'Polio at birth, 6, 10 and 14 weeks; pentavalent at 6, 10 and 14 weeks.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T04', true),
  ('P5_SCI_T04-Q8', 'P5', 'Science', 'Immunisation', 53, 'At what age is the measles vaccine given?', 'At 9 months (with a later second dose).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T04', true),
  ('P5_SCI_T04-Q9', 'P5', 'Science', 'Immunisation', 54, 'What is the cold chain, and why is it necessary?', 'The cold chain is the system of keeping vaccines cold from the factory to the child. It is necessary because vaccines are spoilt by heat and strong light and would then fail to protect the child.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T04', true),
  ('P5_SCI_T04-Q10', 'P5', 'Science', 'Immunisation', 55, 'Give any four ways of caring for vaccines.', 'Any four of: keep them in a refrigerator or cold box with ice packs; carry them in a vaccine carrier; check the temperature with a thermometer; keep them out of sunlight; never use them after the expiry date or when the vial monitor shows they are spoilt.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T04', true),
  ('P5_SCI_T04-Q11', 'P5', 'Science', 'Immunisation', 56, 'What is an immunisation card, and why must it be kept safely?', 'It is the card that shows all the vaccines a child has received and the dates. It must be kept safely so that health workers know which doses are still due, and it is often needed when joining school.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T04', true),
  ('P5_SCI_T04-Q12', 'P5', 'Science', 'Immunisation', 57, 'Give any five importances of immunisation.', 'Any five of: it prevents killer diseases and disabilities; it reduces child deaths; it is cheaper than treatment; it keeps children healthy and in school; it has wiped out smallpox; it protects the whole community.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T04', true),
  ('P5_SCI_T04-Q13', 'P5', 'Science', 'Immunisation', 58, 'Which disease has been wiped out completely by immunisation?', 'Smallpox.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T04', true),
  ('P5_SCI_T04-Q14', 'P5', 'Science', 'Immunisation', 59, 'Give any five problems that hinder immunisation in Uganda.', 'Any five of: ignorance and rumours; long distances and poor roads; power failure spoiling vaccines; parents forgetting or losing the card; insecurity in some areas; shortage of funds, staff or vaccines; religious or cultural objections.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T04', true),
  ('P5_SCI_T04-Q15', 'P5', 'Science', 'Immunisation', 60, 'Suggest a solution to each of: rumours about vaccines, long distance to the clinic, power failure, forgetting the appointment.', 'Rumours — health education by radio, schools and village health teams; long distance — outreach and mobile clinics; power failure — solar fridges, cold boxes and ice packs; forgetting — reminders from village health teams and keeping the card where it is easily seen.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T04', true),
  ('P5_SCI_T05-Q1', 'P5', 'Science', 'The Digestive System', 61, 'What is digestion? What is the digestive system?', 'Digestion is the breaking down of food into a form the body can absorb and use. The digestive system is the system of organs that breaks down food, absorbs it and removes the waste.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T05', true),
  ('P5_SCI_T05-Q2', 'P5', 'Science', 'The Digestive System', 62, 'Name the parts of the alimentary canal in order.', 'Mouth → oesophagus (gullet) → stomach → small intestine → large intestine → rectum → anus.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T05', true),
  ('P5_SCI_T05-Q3', 'P5', 'Science', 'The Digestive System', 63, 'Give the work of: the mouth, the stomach, the small intestine, the large intestine.', 'Mouth — chews the food and mixes it with saliva, which starts digesting starch; stomach — churns food with gastric juice and acid, which kill germs and start digesting protein; small intestine — completes digestion and absorbs the food into the blood; large intestine — absorbs water and mineral salts.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T05', true),
  ('P5_SCI_T05-Q4', 'P5', 'Science', 'The Digestive System', 64, 'What is peristalsis?', 'Peristalsis is the squeezing, wave-like movement of the walls of the alimentary canal that pushes food along.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T05', true),
  ('P5_SCI_T05-Q5', 'P5', 'Science', 'The Digestive System', 65, 'Name the four associated organs of the digestive system and the work of each.', 'Salivary glands — produce saliva; liver — produces bile, stores food and removes poisons; gall bladder — stores bile; pancreas — produces pancreatic juice.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T05', true),
  ('P5_SCI_T05-Q6', 'P5', 'Science', 'The Digestive System', 66, 'Which organ makes bile, where is it stored, and what does bile do?', 'The liver makes bile; it is stored in the gall bladder; bile breaks fats into small drops so they can be digested easily.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T05', true),
  ('P5_SCI_T05-Q7', 'P5', 'Science', 'The Digestive System', 67, 'Name the four types of teeth and the work of each.', 'Incisors — cutting and biting; canines — tearing; premolars — crushing and grinding; molars — chewing and grinding.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T05', true),
  ('P5_SCI_T05-Q8', 'P5', 'Science', 'The Digestive System', 68, 'How many teeth has an adult, and how many has a child?', 'An adult has 32; a child has 20 milk teeth.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T05', true),
  ('P5_SCI_T05-Q9', 'P5', 'Science', 'The Digestive System', 69, 'Into what is each of these digested: starch, protein, fats?', 'Starch → simple sugars (glucose); protein → amino acids; fats → fatty acids and glycerol.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T05', true),
  ('P5_SCI_T05-Q10', 'P5', 'Science', 'The Digestive System', 70, 'Where does most absorption take place, and through what?', 'In the small intestine, through tiny finger-like structures called villi.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T05', true),
  ('P5_SCI_T05-Q11', 'P5', 'Science', 'The Digestive System', 71, 'Name any six diseases or disorders of the digestive system and give the cause of each.', 'Any six, for example: diarrhoea — germs in dirty food and water; dysentery — bacteria or amoeba; cholera — bacteria in contaminated water; typhoid — bacteria in food and water; worms — worm eggs from dirt; constipation — little water and roughage; ulcers — too much acid and skipping meals; tooth decay — sugary foods and poor brushing.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T05', true),
  ('P5_SCI_T05-Q12', 'P5', 'Science', 'The Digestive System', 72, 'Give the signs of dysentery and of intestinal worms.', 'Dysentery: stool with blood and mucus, stomach pain and fever. Worms: stomach pain, pot belly, loss of weight, tiredness and anaemia.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T05', true),
  ('P5_SCI_T05-Q13', 'P5', 'Science', 'The Digestive System', 73, 'What is ORS, and how is a home mixture prepared?', 'ORS is oral rehydration salts, given to replace water and salts lost in diarrhoea. A home mixture: one litre of boiled, cooled water + eight level teaspoons of sugar + half a teaspoon of salt, stirred until dissolved.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T05', true),
  ('P5_SCI_T05-Q14', 'P5', 'Science', 'The Digestive System', 74, 'Give any eight ways of keeping the digestive system healthy.', 'Any eight of: eat a balanced diet with roughage; drink clean boiled water; wash hands with soap; wash fruits and cover food; chew well and eat at regular times; deworm every six months; brush teeth twice a day; use a clean latrine; avoid alcohol and self-medication; seek treatment early.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T05', true),
  ('P5_SCI_T05-Q15', 'P5', 'Science', 'The Digestive System', 75, 'Why should hands be washed with soap before eating?', 'Because germs and worm eggs from dirt, faeces and animals stay on the fingers. When we eat with dirty hands they enter the mouth and cause diarrhoea, dysentery, typhoid, cholera and worms. Soap removes them.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T05', true),
  ('P5_SCI_T06-Q1', 'P5', 'Science', 'Heat Energy', 76, 'What is matter? Give its three properties.', 'Matter is anything that has mass (weight) and occupies space. Properties: it has mass, it occupies space and it exerts pressure.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T06', true),
  ('P5_SCI_T06-Q2', 'P5', 'Science', 'Heat Energy', 77, 'Name the three states of matter and give two examples of each.', 'Solid — stone, ice; liquid — water, milk; gas — air, steam.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T06', true),
  ('P5_SCI_T06-Q3', 'P5', 'Science', 'Heat Energy', 78, 'Name the change of state in each: ice to water; water to steam; steam to water; water to ice.', 'Ice to water — melting; water to steam — evaporation (boiling); steam to water — condensation; water to ice — freezing.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T06', true),
  ('P5_SCI_T06-Q4', 'P5', 'Science', 'Heat Energy', 79, 'Define solute, solvent and solution, with an example of each.', 'Solute — the substance that dissolves, e.g. salt; solvent — the liquid it dissolves in, e.g. water; solution — the mixture formed, e.g. salty water.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T06', true),
  ('P5_SCI_T06-Q5', 'P5', 'Science', 'Heat Energy', 80, 'Give the difference between soluble and insoluble substances, with two examples of each.', 'Soluble substances dissolve, for example salt and sugar; insoluble ones do not, for example sand and stones.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T06', true),
  ('P5_SCI_T06-Q6', 'P5', 'Science', 'Heat Energy', 81, 'Name any six methods of separating mixtures and what each is used for.', 'Any six: hand picking — large pieces; winnowing — light from heavy; sieving — small from large; filtering — solids from liquids; decanting — settled solids from a liquid; evaporation — a dissolved solid; distillation — a pure liquid; magnetic separation — magnetic materials.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T06', true),
  ('P5_SCI_T06-Q7', 'P5', 'Science', 'Heat Energy', 82, 'How would you separate: salt from salty water; iron filings from sand; chaff from millet; mud from water?', 'Salt from salty water — evaporation; iron filings from sand — a magnet; chaff from millet — winnowing; mud from water — filtering (or decanting first).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T06', true),
  ('P5_SCI_T06-Q8', 'P5', 'Science', 'Heat Energy', 83, 'What is heat? Name any five sources of heat.', 'Heat is a form of energy that makes things hot. Sources: the sun, fire from firewood or charcoal, electricity, friction, chemical reactions (also geothermal heat and the body).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T06', true),
  ('P5_SCI_T06-Q9', 'P5', 'Science', 'Heat Energy', 84, 'Name the three ways in which heat travels and say where each mainly occurs.', 'Conduction — mainly in solids; convection — in liquids and gases; radiation — through empty space, needing no material.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T06', true),
  ('P5_SCI_T06-Q10', 'P5', 'Science', 'Heat Energy', 85, 'Describe an experiment to show conduction of heat.', 'Take a metal rod and stick pins along it with wax. Heat one end in a flame. The wax melts and the pins fall one after another from the hot end outwards, showing that heat travelled along the solid by conduction.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T06', true),
  ('P5_SCI_T06-Q11', 'P5', 'Science', 'Heat Energy', 86, 'Describe an experiment to show convection in water.', 'Heat water gently in a clear glass container and drop in a coloured crystal (or sawdust). The colour rises from the heated part, spreads at the top, sinks at the sides and circles, showing convection currents.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T06', true),
  ('P5_SCI_T06-Q12', 'P5', 'Science', 'Heat Energy', 87, 'Name any four good conductors and any four poor conductors of heat.', 'Good conductors: copper, aluminium, iron, silver. Poor conductors: wood, plastic, rubber, glass (also dry cloth, air, paper).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T06', true),
  ('P5_SCI_T06-Q13', 'P5', 'Science', 'Heat Energy', 88, 'Why are saucepans made of metal but their handles of wood or plastic?', 'The metal body conducts heat quickly to the food so it cooks fast, while the wooden or plastic handle is a poor conductor, so it stays cool and the cook is not burnt.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T06', true),
  ('P5_SCI_T06-Q14', 'P5', 'Science', 'Heat Energy', 89, 'Give any five effects of heat on matter.', 'Any five of: expansion when heated and contraction when cooled; change of state; burning; drying; killing germs; cooking food.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T06', true),
  ('P5_SCI_T06-Q15', 'P5', 'Science', 'Heat Energy', 90, 'Give any five uses and any four dangers of heat.', 'Uses (any five): cooking; boiling water to kill germs; warming the body and house; drying clothes and food; ironing; welding; generating electricity; making bricks and pots. Dangers (any four): burns and scalds; fires; smoke causing chest disease; suffocation from a charcoal stove in a closed room.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T06', true),
  ('P5_SCI_T07-Q1', 'P5', 'Science', 'Occupations in Our Community — Crop Growing', 91, 'What is a tuber? Give the two types with two examples of each.', 'A tuber is a swollen underground part of a plant in which food is stored. Root tubers — sweet potatoes and cassava; stem tubers — Irish potatoes and some yams.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T07', true),
  ('P5_SCI_T07-Q2', 'P5', 'Science', 'Occupations in Our Community — Crop Growing', 92, 'How can you tell a stem tuber from a root tuber?', 'A stem tuber has buds or "eyes" from which new shoots grow; a root tuber has no eyes and is grown from cuttings or the crown.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T07', true),
  ('P5_SCI_T07-Q3', 'P5', 'Science', 'Occupations in Our Community — Crop Growing', 93, 'What planting material is used for: sweet potatoes, cassava, Irish potatoes, carrots?', 'Sweet potatoes — vine cuttings; cassava — stem cuttings; Irish potatoes — seed tubers with eyes; carrots — seeds.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T07', true),
  ('P5_SCI_T07-Q4', 'P5', 'Science', 'Occupations in Our Community — Crop Growing', 94, 'Give the steps followed in growing a tuber crop.', 'Choose a suitable site → prepare the land into ridges or mounds → select clean planting materials → plant at the right spacing at the start of the rains → weed regularly → earth up → apply manure and rotate crops → control pests and diseases → harvest and store properly.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T07', true),
  ('P5_SCI_T07-Q5', 'P5', 'Science', 'Occupations in Our Community — Crop Growing', 95, 'Why are tuber crops planted on ridges or mounds?', 'Because ridges and mounds give loose, deep soil for the tubers to swell in, and they drain well so the tubers do not rot.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T07', true),
  ('P5_SCI_T07-Q6', 'P5', 'Science', 'Occupations in Our Community — Crop Growing', 96, 'What is earthing up, and why is it done?', 'Earthing up is heaping soil around the base of the plants. It covers the tubers so they do not become green or be attacked by weevils, supports the plant and controls weeds.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T07', true),
  ('P5_SCI_T07-Q7', 'P5', 'Science', 'Occupations in Our Community — Crop Growing', 97, 'Name any five pests of tuber crops and the damage each causes.', 'Any five: sweet potato weevil — bores into tubers, making them bitter; moles and rats — eat tubers underground; termites — eat stems and roots; aphids and whiteflies — suck sap and spread viruses; nematodes — cause galls and stunted plants.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T07', true),
  ('P5_SCI_T07-Q8', 'P5', 'Science', 'Occupations in Our Community — Crop Growing', 98, 'Name any four diseases of tuber crops and their signs.', 'Any four: cassava mosaic — yellow, twisted, small leaves; cassava brown streak — brown rot inside the tuber; potato blight — leaves turn black and the plant dies; bacterial wilt — sudden wilting and death.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T07', true),
  ('P5_SCI_T07-Q9', 'P5', 'Science', 'Occupations in Our Community — Crop Growing', 99, 'Which insect spreads cassava mosaic?', 'The whitefly.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T07', true),
  ('P5_SCI_T07-Q10', 'P5', 'Science', 'Occupations in Our Community — Crop Growing', 100, 'Give any six ways of controlling pests and diseases of tuber crops.', 'Any six of: plant clean, disease-free materials; use resistant varieties; practise crop rotation; earth up; weed and keep the garden clean; remove and burn diseased plants; harvest in time; trap rats and moles; use pesticides correctly; seek advice from the extension officer.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T07', true),
  ('P5_SCI_T07-Q11', 'P5', 'Science', 'Occupations in Our Community — Crop Growing', 101, 'Why should a farmer plant clean, disease-free cuttings?', 'Because diseases such as cassava mosaic and brown streak are carried in the cuttings themselves. Planting infected material spreads the disease to the whole garden, however well the farmer weeds or sprays.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T07', true),
  ('P5_SCI_T07-Q12', 'P5', 'Science', 'Occupations in Our Community — Crop Growing', 102, 'Give any four rules for harvesting tuber crops.', 'Any four of: dig carefully with a hoe or fork so the tubers are not cut or bruised; harvest when mature; harvest sweet potatoes piecemeal as needed; lift Irish potatoes when the leaves turn yellow; avoid harvesting in very wet conditions; keep damaged tubers separate.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T07', true),
  ('P5_SCI_T07-Q13', 'P5', 'Science', 'Occupations in Our Community — Crop Growing', 103, 'Give any five ways of storing tuber crops well.', 'Any five of: keep them in a cool, dry, dark, airy place; sort out damaged ones first; store Irish potatoes in crates or on racks, not heaps; dry cassava and make flour; slice and dry sweet potatoes; protect the store from rats and termites.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T07', true),
  ('P5_SCI_T07-Q14', 'P5', 'Science', 'Occupations in Our Community — Crop Growing', 104, 'Give any five uses of tuber crops.', 'Any five of: food rich in carbohydrates; income when sold; animal feed from peelings and vines; raw material for flour, starch and chips; planting material for the next season.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T07', true),
  ('P5_SCI_T07-Q15', 'P5', 'Science', 'Occupations in Our Community — Crop Growing', 105, 'Which tuber crop grows best in cool areas such as Kabale, and which one resists drought best?', 'Irish potatoes grow best in cool areas such as Kabale; cassava resists drought best.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T07', true),
  ('P5_SCI_T08-Q1', 'P5', 'Science', 'Bacteria and Fungi', 106, 'What are bacteria, and what instrument is used to see them?', 'Bacteria are very tiny living things (micro-organisms) that can only be seen with a microscope.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T08', true),
  ('P5_SCI_T08-Q2', 'P5', 'Science', 'Bacteria and Fungi', 107, 'Give any five characteristics of bacteria.', 'Any five of: they are very small; they are living and multiply very fast by splitting into two; they have different shapes — round, rod, spiral, comma; most need warmth, moisture, food and darkness; some form spores; some need air and others do not.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T08', true),
  ('P5_SCI_T08-Q3', 'P5', 'Science', 'Bacteria and Fungi', 108, 'Where are bacteria found, and where do they breed best?', 'They are found everywhere — in air, water, soil, food, on the skin and in the body. They breed best in warm, moist, dirty places such as rubbish heaps, stagnant water, uncovered food and dirty latrines.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T08', true),
  ('P5_SCI_T08-Q4', 'P5', 'Science', 'Bacteria and Fungi', 109, 'Give any five ways in which bacteria are useful.', 'Any five of: making yoghurt, sour milk and cheese; causing decay that returns nutrients to the soil; making manure and compost; fixing nitrogen in legume root nodules; helping digestion in the intestines; making vinegar, medicines and antibiotics; treating sewage; producing biogas.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T08', true),
  ('P5_SCI_T08-Q5', 'P5', 'Science', 'Bacteria and Fungi', 110, 'Name any six diseases caused by bacteria and how each is spread.', 'Any six: cholera — dirty water and food; typhoid — contaminated food and water; dysentery — dirty hands and flies; TB — coughing and sneezing; whooping cough and diphtheria — air; tetanus — dirt in wounds; pneumonia — droplets in air.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T08', true),
  ('P5_SCI_T08-Q6', 'P5', 'Science', 'Bacteria and Fungi', 111, 'What are fungi? Give any four examples.', 'Fungi are living things that have no chlorophyll, so they cannot make their own food, and feed on dead or living matter. Examples: mushrooms, yeast, moulds, the ringworm fungus.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T08', true),
  ('P5_SCI_T08-Q7', 'P5', 'Science', 'Bacteria and Fungi', 112, 'Give any four characteristics of fungi.', 'Any four of: they have no chlorophyll; they have no true roots, stems or leaves; they reproduce by spores; they grow in warm, damp, dark places; some are saprophytes and some parasites.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T08', true),
  ('P5_SCI_T08-Q8', 'P5', 'Science', 'Bacteria and Fungi', 113, 'Give the difference between a saprophyte and a parasite.', 'A saprophyte feeds on dead matter, for example the mould on bread; a parasite feeds on a living host, for example the ringworm fungus on human skin.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T08', true),
  ('P5_SCI_T08-Q9', 'P5', 'Science', 'Bacteria and Fungi', 114, 'Give any four ways in which fungi are useful.', 'Any four of: edible mushrooms as food; yeast for baking and brewing; penicillin and other medicines; causing decay that enriches the soil; flavouring cheese.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T08', true),
  ('P5_SCI_T08-Q10', 'P5', 'Science', 'Bacteria and Fungi', 115, 'Give any four ways in which fungi are harmful.', 'Any four of: they cause human diseases such as ringworm; they cause crop diseases such as blight; they spoil food, leather, clothes and books; some mushrooms are poisonous; moulds produce aflatoxins.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T08', true),
  ('P5_SCI_T08-Q11', 'P5', 'Science', 'Bacteria and Fungi', 116, 'Name two fungal diseases of human beings and two of crops.', 'Human: ringworm and athlete''s foot (also thrush). Crops: potato blight and coffee leaf rust (also maize smut).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T08', true),
  ('P5_SCI_T08-Q12', 'P5', 'Science', 'Bacteria and Fungi', 117, 'What are aflatoxins, and how can they be prevented?', 'Aflatoxins are poisons produced by moulds growing on badly dried food such as groundnuts and maize. They are prevented by drying the produce properly, storing it in a dry, airy place, and throwing away mouldy or discoloured grain.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T08', true),
  ('P5_SCI_T08-Q13', 'P5', 'Science', 'Bacteria and Fungi', 118, 'Give any eight ways of preventing bacterial and fungal diseases.', 'Any eight of: bathe daily and wash hands with soap; wash, cover and cook food well; boil or treat drinking water; use latrines and dispose of rubbish properly; keep the body and clothes dry; do not share towels, combs or razor blades; sterilise instruments and use antiseptic on wounds; immunise children; take prescribed medicines correctly; dry and store food well.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T08', true),
  ('P5_SCI_T08-Q14', 'P5', 'Science', 'Bacteria and Fungi', 119, 'Why should a person finish the full course of antibiotics?', 'Because stopping early leaves some bacteria alive. They then multiply and become resistant, so the same medicine no longer works and the illness returns and is harder to treat.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T08', true),
  ('P5_SCI_T08-Q15', 'P5', 'Science', 'Bacteria and Fungi', 120, 'Why does ironing clothes and drying them in the sun help to prevent skin diseases?', 'Because the fungi and their spores, and parasites such as jiggers and lice, live in damp cloth. The sun''s heat and the hot iron kill them, so the clothes are safe to wear.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T08', true),
  ('P5_SCI_T09-Q1', 'P5', 'Science', 'Types of Change — Biological, Physical and Chemical', 121, 'What is change? Name the three types.', 'Change is something becoming different from what it was. The three types are biological, physical and chemical.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T09', true),
  ('P5_SCI_T09-Q2', 'P5', 'Science', 'Types of Change — Biological, Physical and Chemical', 122, 'Name any five agents of change.', 'Any five of: heat and cold, water, air (oxygen and wind), living things such as bacteria, fungi, plants, animals and people, time, chemicals.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T09', true),
  ('P5_SCI_T09-Q3', 'P5', 'Science', 'Types of Change — Biological, Physical and Chemical', 123, 'What is a biological change? Give any four examples.', 'A biological change is a change that happens in living things as they grow and develop. Examples: germination of a seed; growth of a chick into a hen; a tadpole becoming a frog; decay of dead matter; healing of a wound (any four).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T09', true),
  ('P5_SCI_T09-Q4', 'P5', 'Science', 'Types of Change — Biological, Physical and Chemical', 124, 'Give the stages of growth in a human being.', 'Baby → child → adolescent → adult → old person.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T09', true),
  ('P5_SCI_T09-Q5', 'P5', 'Science', 'Types of Change — Biological, Physical and Chemical', 125, 'Give four physical changes that happen to girls and four that happen to boys at adolescence.', 'Girls: breasts develop; hips widen; menstruation begins; pubic and armpit hair grows. Boys: the voice deepens; shoulders broaden; wet dreams begin; pubic, armpit and facial hair grows.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T09', true),
  ('P5_SCI_T09-Q6', 'P5', 'Science', 'Types of Change — Biological, Physical and Chemical', 126, 'Give any six ways of caring for the body during these changes.', 'Any six of: bathe daily and wash the private parts with clean water; wear clean cotton underwear and change it daily; use and change clean sanitary materials; keep nails short and hair clean; eat well and rest; talk to a trusted adult about worries; choose good friends; abstain from sex.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T09', true),
  ('P5_SCI_T09-Q7', 'P5', 'Science', 'Types of Change — Biological, Physical and Chemical', 127, 'What should a child do if somebody tries to touch his or her private parts?', 'The child should say NO firmly, move away and tell a trusted adult at once — a parent, teacher, health worker, religious leader or the police. It must not be kept secret, and it is never the child''s fault.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T09', true),
  ('P5_SCI_T09-Q8', 'P5', 'Science', 'Types of Change — Biological, Physical and Chemical', 128, 'What is a physical change? Give any five examples.', 'A physical change is one in which no new substance is formed and which can usually be reversed. Examples: melting ice; boiling water; dissolving salt; breaking a stick; bending a wire (any five).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T09', true),
  ('P5_SCI_T09-Q9', 'P5', 'Science', 'Types of Change — Biological, Physical and Chemical', 129, 'What is a chemical change? Give any five examples.', 'A chemical change is one in which a new substance is formed and which usually cannot be reversed. Examples: burning wood; rusting of iron; cooking food; souring of milk; rotting of fruit (any five).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T09', true),
  ('P5_SCI_T09-Q10', 'P5', 'Science', 'Types of Change — Biological, Physical and Chemical', 130, 'Give three differences between physical and chemical changes.', 'In a physical change no new substance is formed, it is usually reversible, and only shape, size or state changes; in a chemical change a new substance is formed, it is usually irreversible, and heat, light, gas or a smell is often produced.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T09', true),
  ('P5_SCI_T09-Q11', 'P5', 'Science', 'Types of Change — Biological, Physical and Chemical', 131, 'Classify each as physical or chemical: melting ice, burning wood, dissolving salt, rusting iron, breaking glass, souring milk.', 'Melting ice — physical; burning wood — chemical; dissolving salt — physical; rusting iron — chemical; breaking glass — physical; souring milk — chemical.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T09', true),
  ('P5_SCI_T09-Q12', 'P5', 'Science', 'Types of Change — Biological, Physical and Chemical', 132, 'What two things are needed for iron to rust?', 'Air (oxygen) and water (moisture).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T09', true),
  ('P5_SCI_T09-Q13', 'P5', 'Science', 'Types of Change — Biological, Physical and Chemical', 133, 'Give any four ways of preventing rusting.', 'Any four of: painting; oiling or greasing; galvanising (coating with zinc); coating with plastic; keeping the metal dry; using stainless steel or non-rusting metals.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T09', true),
  ('P5_SCI_T09-Q14', 'P5', 'Science', 'Types of Change — Biological, Physical and Chemical', 134, 'What is metamorphosis? Give the stages for a butterfly.', 'Metamorphosis is the change of form as an animal grows. For a butterfly: egg → larva (caterpillar) → pupa → adult butterfly.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T09', true),
  ('P5_SCI_T09-Q15', 'P5', 'Science', 'Types of Change — Biological, Physical and Chemical', 135, 'Why is cooking food said to be a chemical change?', 'Because cooking forms new substances — the food changes in colour, smell, taste and texture, and it cannot be turned back into the raw food it was.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T09', true),
  ('P5_SCI_T10-Q1', 'P5', 'Science', 'Keeping Goats, Sheep and Pigs', 136, 'Name any six external parts of a goat.', 'Any six of: head, horns, beard, eyes, ears, nostrils, mouth, neck, back, udder or scrotum, legs, hooves, tail.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T10', true),
  ('P5_SCI_T10-Q2', 'P5', 'Science', 'Keeping Goats, Sheep and Pigs', 137, 'Give four differences between a goat and a sheep.', 'A goat has a beard, a tail that points up, a coat of hair, and it browses on leaves; a sheep has no beard, a tail that hangs down, a woolly fleece, and it grazes on grass.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T10', true),
  ('P5_SCI_T10-Q3', 'P5', 'Science', 'Keeping Goats, Sheep and Pigs', 138, 'Name two local and two exotic breeds of goats.', 'Local: Small East African and Mubende. Exotic: Toggenburg and Saanen (also Alpine, Boer).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T10', true),
  ('P5_SCI_T10-Q4', 'P5', 'Science', 'Keeping Goats, Sheep and Pigs', 139, 'Name two local and two exotic breeds of sheep.', 'Local: East African Blackhead and Masai. Exotic: Merino and Dorper (also Corriedale).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T10', true),
  ('P5_SCI_T10-Q5', 'P5', 'Science', 'Keeping Goats, Sheep and Pigs', 140, 'Give any five uses of goats and sheep.', 'Any five of: meat; milk; skins and hides; wool from sheep; manure; income and school fees; ceremonies; easy to keep on small land.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T10', true),
  ('P5_SCI_T10-Q6', 'P5', 'Science', 'Keeping Goats, Sheep and Pigs', 141, 'Name any six external parts of a pig.', 'Any six of: snout, eyes, ears, bristles, back, hooves (cloven feet), curly tail, udder with teats, flank.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T10', true),
  ('P5_SCI_T10-Q7', 'P5', 'Science', 'Keeping Goats, Sheep and Pigs', 142, 'Name any three exotic breeds of pigs.', 'Any three of: Large White, Landrace, Duroc, Hampshire.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T10', true),
  ('P5_SCI_T10-Q8', 'P5', 'Science', 'Keeping Goats, Sheep and Pigs', 143, 'Give the meaning of: boar, sow, gilt, farrowing.', 'Boar — a male pig; sow — a female pig that has produced; gilt — a young female pig; farrowing — a pig giving birth.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T10', true),
  ('P5_SCI_T10-Q9', 'P5', 'Science', 'Keeping Goats, Sheep and Pigs', 144, 'What is the gestation period of a pig?', 'About 114 days — three months, three weeks and three days.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T10', true),
  ('P5_SCI_T10-Q10', 'P5', 'Science', 'Keeping Goats, Sheep and Pigs', 145, 'Give any six qualities of a good house for goats, sheep or pigs.', 'Any six of: raised and well-drained floor; well ventilated but not draughty; strong walls and a leak-proof roof; easy to clean with a slope and drainage; separate pens for the young and the sick; feeding troughs and drinkers; enough space; shade or a wallow for pigs.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T10', true),
  ('P5_SCI_T10-Q11', 'P5', 'Science', 'Keeping Goats, Sheep and Pigs', 146, 'Why must a pig house have shade or a wallow?', 'Because pigs cannot sweat, so they cannot cool themselves in the usual way. Shade and a wallow keep them cool and also help control external parasites.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T10', true),
  ('P5_SCI_T10-Q12', 'P5', 'Science', 'Keeping Goats, Sheep and Pigs', 147, 'Give any six ways of managing goats, sheep and pigs well.', 'Any six of: give clean water always; feed a balanced ration with mineral licks; deworm and vaccinate; spray or dip against parasites; clean the house daily; trim hooves; handle them gently; isolate sick animals; keep records; castrate males not needed for breeding.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T10', true),
  ('P5_SCI_T10-Q13', 'P5', 'Science', 'Keeping Goats, Sheep and Pigs', 148, 'Name the products got from goats, from sheep and from pigs.', 'Goats: meat, milk, skins, manure, income. Sheep: meat, wool, skins, manure. Pigs: pork, bacon, ham, sausages, lard, bristles, manure.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T10', true),
  ('P5_SCI_T10-Q14', 'P5', 'Science', 'Keeping Goats, Sheep and Pigs', 149, 'Name any four external and any three internal parasites of these animals.', 'External: ticks, lice, mites, fleas (also tsetse flies). Internal: round worms, tape worms, liver flukes (also lung worms).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T10', true),
  ('P5_SCI_T10-Q15', 'P5', 'Science', 'Keeping Goats, Sheep and Pigs', 150, 'Name any five diseases, their signs and how each is prevented or controlled.', 'Any five, for example: pneumonia — coughing and fever, prevented by warm dry housing and treated early; foot and mouth — mouth and hoof sores, controlled by vaccination and quarantine; mange — itching and hair loss, controlled by spraying; worms — thin body and pot belly, controlled by deworming; African swine fever — high fever and sudden death, controlled only by hygiene and quarantine, as there is no cure.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T10', true),
  ('P5_SCI_T11-Q1', 'P5', 'Science', 'Food and Nutrition', 151, 'What is breastfeeding? For how long should a baby be breastfed exclusively?', 'Breastfeeding is feeding a baby on milk from the mother''s breast. A baby should be breastfed exclusively for the first six months, then breastfed with other foods up to two years or beyond.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T11', true),
  ('P5_SCI_T11-Q2', 'P5', 'Science', 'Food and Nutrition', 152, 'Give any four advantages of breastfeeding to the baby and two to the mother.', 'To the baby (any four): breast milk is complete food; colostrum gives antibodies; it is clean, warm and ready; it is easy to digest; it builds love between mother and baby. To the mother: it costs nothing; it helps the womb return to normal (also delays another pregnancy).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T11', true),
  ('P5_SCI_T11-Q3', 'P5', 'Science', 'Food and Nutrition', 153, 'What is colostrum, and why is it important?', 'Colostrum is the first thick yellow milk produced after birth. It is important because it is rich in antibodies that protect the baby from disease, and in nutrients for a good start.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T11', true),
  ('P5_SCI_T11-Q4', 'P5', 'Science', 'Food and Nutrition', 154, 'What is bottle feeding? Give two advantages and four disadvantages.', 'Bottle feeding is feeding a baby milk from a bottle. Advantages: anybody can feed the baby; the amount can be measured. Disadvantages: bottles are easily contaminated and cause diarrhoea; formula and bottles are expensive; there are no antibodies; the bond with the mother is weaker; over-dilution causes malnutrition.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T11', true),
  ('P5_SCI_T11-Q5', 'P5', 'Science', 'Food and Nutrition', 155, 'If a mother must bottle feed, what four rules must she follow?', 'Sterilise the bottle and teat by boiling; use boiled water; mix exactly as instructed; feed the milk at once and never keep left-overs (using a cup and spoon is safer).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T11', true),
  ('P5_SCI_T11-Q6', 'P5', 'Science', 'Food and Nutrition', 156, 'Who are vulnerable people? Name any five groups.', 'Vulnerable people are those most easily harmed by poor feeding and disease. Any five of: babies and young children; expectant mothers; breastfeeding mothers; the sick, including people with HIV; the elderly; people with disabilities.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T11', true),
  ('P5_SCI_T11-Q7', 'P5', 'Science', 'Food and Nutrition', 157, 'What foods does an expectant mother especially need, and why?', 'She needs iron-rich foods (dodo, liver, beans), protein, fruits and vegetables and plenty of water, because she is feeding herself and the growing baby and is at risk of anaemia.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T11', true),
  ('P5_SCI_T11-Q8', 'P5', 'Science', 'Food and Nutrition', 158, 'Name the seven food values and give one example of each.', 'Carbohydrates — matooke; proteins — beans; fats and oils — cooking oil; vitamins — fruits; mineral salts — milk; water — clean drinking water; roughage — vegetables.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T11', true),
  ('P5_SCI_T11-Q9', 'P5', 'Science', 'Food and Nutrition', 159, 'What is a balanced diet? Give an example of a balanced meal from your home.', 'A balanced diet is a meal containing all the food values in the right amounts. Example: matooke with beans, greens, a fruit and water.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T11', true),
  ('P5_SCI_T11-Q10', 'P5', 'Science', 'Food and Nutrition', 160, 'Name any six deficiency diseases and the food value missing in each.', 'Any six: kwashiorkor — protein; marasmus — energy and protein; anaemia — iron; rickets — vitamin D and calcium; night blindness — vitamin A; scurvy — vitamin C; goitre — iodine; beriberi — vitamin B1.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T11', true),
  ('P5_SCI_T11-Q11', 'P5', 'Science', 'Food and Nutrition', 161, 'Give the signs of kwashiorkor and of marasmus.', 'Kwashiorkor: swollen legs and face, thin light hair, pot belly, misery and loss of appetite. Marasmus: very thin body, "old man''s face", loose skin, ribs showing.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T11', true),
  ('P5_SCI_T11-Q12', 'P5', 'Science', 'Food and Nutrition', 162, 'How can anaemia be prevented?', 'By eating iron-rich foods such as dodo, nakati, liver, beans and meat, together with vitamin C fruits to absorb the iron; by deworming regularly; by sleeping under a treated mosquito net to avoid malaria; and by treating bleeding early.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T11', true),
  ('P5_SCI_T11-Q13', 'P5', 'Science', 'Food and Nutrition', 163, 'Give any six rules of food hygiene.', 'Any six of: wash hands with soap before handling food and eating; wash fruits and vegetables; use clean water and utensils; cover food against flies; keep animals out of the kitchen; do not let a person with diarrhoea or a wound cook for others; wash the cooking place daily.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T11', true),
  ('P5_SCI_T11-Q14', 'P5', 'Science', 'Food and Nutrition', 164, 'Give any four ways of preparing food so that the food value is not lost.', 'Any four of: do not overcook vegetables; steam rather than boil; use the cooking water in the sauce; cut vegetables just before cooking; cook with the lid on; avoid too much oil and salt.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T11', true),
  ('P5_SCI_T11-Q15', 'P5', 'Science', 'Food and Nutrition', 165, 'Give any five ways of storing food well, and say why mouldy groundnuts must never be eaten.', 'Any five of: dry grains and legumes well; store in clean, dry, airy places; use sacks on pallets or granaries; protect from rats, weevils and moulds; keep milk, meat and cooked food covered and cool and reheat well. Mouldy groundnuts must never be eaten because the moulds produce aflatoxins, poisons that damage the liver and can cause cancer.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T11', true),
  ('P5_SCI_T12-Q1', 'P5', 'Science', 'Primary Health Care and Family Care', 166, 'What is Primary Health Care?', 'Primary Health Care is essential health care made available to all people in the community at a cost they can afford, with their full participation, aimed at preventing disease and promoting health.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T12', true),
  ('P5_SCI_T12-Q2', 'P5', 'Science', 'Primary Health Care and Family Care', 167, 'Name any six elements of PHC.', 'Any six of: health education; proper nutrition; safe water and basic sanitation; maternal and child health including family planning; immunisation; prevention and control of local endemic diseases; treatment of common diseases and injuries; provision of essential drugs; control of HIV/AIDS; care of the disabled and elderly.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T12', true),
  ('P5_SCI_T12-Q3', 'P5', 'Science', 'Primary Health Care and Family Care', 168, 'Name any four principles of PHC and explain two.', 'Any four of: community participation, equitable distribution, appropriate technology, intersectoral collaboration, focus on prevention, affordability. (Explain two, for example: community participation means the people themselves plan and run their health services; appropriate technology means using simple, cheap methods such as pit latrines and ORS that the community can manage.)', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T12', true),
  ('P5_SCI_T12-Q4', 'P5', 'Science', 'Primary Health Care and Family Care', 169, 'Why is prevention said to be better than cure?', 'Because preventing a disease costs far less than treating it, saves lives and suffering, keeps children in school and adults at work, and stops the disease from spreading to others.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T12', true),
  ('P5_SCI_T12-Q5', 'P5', 'Science', 'Primary Health Care and Family Care', 170, 'Give any six PHC activities that promote community hygiene.', 'Any six of: digging rubbish pits and using latrines; protecting water sources; draining stagnant water and clearing bushes; building drying racks, bath shelters and hand-washing facilities; health education; immunisation days; kitchen gardens; school health clubs and clean-up days.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T12', true),
  ('P5_SCI_T12-Q6', 'P5', 'Science', 'Primary Health Care and Family Care', 171, 'Give any five responsibilities of an individual in keeping healthy.', 'Any five of: keep the body clean; eat a balanced diet; use the latrine and wash hands with soap; sleep under a treated net; seek treatment early; avoid alcohol, smoking and drug abuse; keep the surroundings clean.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T12', true),
  ('P5_SCI_T12-Q7', 'P5', 'Science', 'Primary Health Care and Family Care', 172, 'Give any five responsibilities of a family in keeping its members healthy.', 'Any five of: build and maintain a latrine, bath shelter, rubbish pit and drying rack; boil or treat drinking water; feed the family well; take children for immunisation; care for the sick, elderly and disabled; keep the home and compound clean.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T12', true),
  ('P5_SCI_T12-Q8', 'P5', 'Science', 'Primary Health Care and Family Care', 173, 'Give any four responsibilities of the community and four of the government.', 'Community: protect water sources; hold clean-up days; support village health teams; build and maintain health centres (also report outbreaks). Government: train and pay health workers; supply drugs and vaccines; build health centres; make and enforce public health laws (also run health campaigns).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T12', true),
  ('P5_SCI_T12-Q9', 'P5', 'Science', 'Primary Health Care and Family Care', 174, 'What is a family? Name the four types.', 'A family is a group of people related by blood, marriage or adoption who live together and care for one another. Types: nuclear, extended, single-parent and child-headed.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T12', true),
  ('P5_SCI_T12-Q10', 'P5', 'Science', 'Primary Health Care and Family Care', 175, 'Give any five duties of parents and five duties of children.', 'Parents: provide food, shelter, clothing, medical care and education; give love, guidance and discipline; protect the children. Children: obey and respect parents; help with chores; go to school and work hard; care for younger ones and the elderly; keep clean; report anything that frightens or hurts them.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T12', true),
  ('P5_SCI_T12-Q11', 'P5', 'Science', 'Primary Health Care and Family Care', 176, 'How should the family care for a sick person?', 'Give clean bedding and a quiet, airy room; provide soft, tasty food and plenty of fluids; give the medicine on time and complete the dose; keep the person clean and comfortable; watch for danger signs and take them to a health worker quickly.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T12', true),
  ('P5_SCI_T12-Q12', 'P5', 'Science', 'Primary Health Care and Family Care', 177, 'How should the family care for the elderly and for people with disabilities?', 'The elderly need soft food, warmth, company, help with washing and moving, and respect. People with disabilities need support without pity, help to attend school and work, assistive aids where possible, and full inclusion in family activities.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T12', true),
  ('P5_SCI_T12-Q13', 'P5', 'Science', 'Primary Health Care and Family Care', 178, 'Name any six things found in a healthy home.', 'Any six of: a clean compound; a latrine; a rubbish pit; a drying rack; a bath shelter; a kitchen with a raised fireplace; clean covered water storage; mosquito nets on the beds; a kitchen garden.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T12', true),
  ('P5_SCI_T12-Q14', 'P5', 'Science', 'Primary Health Care and Family Care', 179, 'Who are village health teams, and what do they do?', 'Village health teams are trained community volunteers. They teach families about health, encourage immunisation and use of latrines and nets, treat or refer simple illnesses, follow up sick people and report outbreaks.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T12', true),
  ('P5_SCI_T12-Q15', 'P5', 'Science', 'Primary Health Care and Family Care', 180, 'Give any four ways in which a school can practise PHC.', 'Any four of: keeping the compound and latrines clean; running hand-washing points with soap; a school health club with drama, posters and talks; growing vegetables in a school garden; inspecting pupils'' hygiene; inviting health workers; deworming and immunisation days.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P5_SCI_T12', true),
  ('P6_SCI_T01-Q1', 'P6', 'Science', 'Classification of Animals', 1, 'What is classification, and give two reasons why animals are classified?', 'Classification is the grouping of living things according to their similarities and differences. Reasons: it makes study easier and it helps us identify animals and know how to care for them.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T01', true),
  ('P6_SCI_T01-Q2', 'P6', 'Science', 'Classification of Animals', 2, 'Give the difference between vertebrates and invertebrates.', 'Vertebrates have a backbone; invertebrates do not.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T01', true),
  ('P6_SCI_T01-Q3', 'P6', 'Science', 'Classification of Animals', 3, 'Name the five classes of vertebrates and one example of each.', 'Mammals — cow; birds — hen; reptiles — lizard; fish — tilapia; amphibians — frog.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T01', true),
  ('P6_SCI_T01-Q4', 'P6', 'Science', 'Classification of Animals', 4, 'Which two classes of vertebrates are warm-blooded?', 'Mammals and birds.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T01', true),
  ('P6_SCI_T01-Q5', 'P6', 'Science', 'Classification of Animals', 5, 'Give any four characteristics of mammals.', 'Any four of: body covered with hair or fur; have mammary glands and feed young on milk; give birth to live young; breathe using lungs; are warm-blooded; have external ears.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T01', true),
  ('P6_SCI_T01-Q6', 'P6', 'Science', 'Classification of Animals', 6, 'Give any four characteristics of birds.', 'Any four of: body covered with feathers; have a beak; have two wings and two legs; lay eggs with hard shells; are warm-blooded; have light hollow bones.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T01', true),
  ('P6_SCI_T01-Q7', 'P6', 'Science', 'Classification of Animals', 7, 'Give three differences between reptiles and amphibians.', 'Reptiles: dry scaly skin, live on land (or water) and breathe with lungs all their life, lay leathery eggs on land. Amphibians: moist smooth skin, live both in water and on land, young breathe with gills and adults with lungs and skin, lay eggs in water. (Any three pairs.)', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T01', true),
  ('P6_SCI_T01-Q8', 'P6', 'Science', 'Classification of Animals', 8, 'How do fish breathe, and how do they move in water?', 'Fish breathe using gills, and they move using fins and a tail.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T01', true),
  ('P6_SCI_T01-Q9', 'P6', 'Science', 'Classification of Animals', 9, 'Name the three main groups of invertebrates.', 'Arthropods, molluscs and worms.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T01', true),
  ('P6_SCI_T01-Q10', 'P6', 'Science', 'Classification of Animals', 10, 'Name the four groups of arthropods and give one example of each.', 'Insects — housefly; arachnids — spider; myriapods — millipede; crustaceans — crab.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T01', true),
  ('P6_SCI_T01-Q11', 'P6', 'Science', 'Classification of Animals', 11, 'Give three differences between insects and arachnids.', 'Insects have 6 legs, arachnids have 8; insects have 3 body parts, arachnids 2; most insects have wings and antennae, arachnids have neither.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T01', true),
  ('P6_SCI_T01-Q12', 'P6', 'Science', 'Classification of Animals', 12, 'Give the difference between a millipede and a centipede.', 'A millipede has two pairs of legs on each body segment and rolls up when touched; a centipede has one pair per segment and is a fast-moving hunter with poison claws.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T01', true),
  ('P6_SCI_T01-Q13', 'P6', 'Science', 'Classification of Animals', 13, 'Why is a bat classified as a mammal and not a bird?', 'Because it has hair on its body, mammary glands and gives birth to live young which it feeds on milk — even though it flies, it has no feathers or beak.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T01', true),
  ('P6_SCI_T01-Q14', 'P6', 'Science', 'Classification of Animals', 14, 'Give any five ways of caring for animals.', 'Any five of: give clean food and water; provide clean dry shelter; treat and vaccinate them; handle them gently; protect them from thieves and wild animals; do not poach; protect their habitats.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T01', true),
  ('P6_SCI_T01-Q15', 'P6', 'Science', 'Classification of Animals', 15, 'Give any five uses of animals to human beings.', 'Any five of: food such as meat, milk, eggs and honey; hides and skins; manure; transport and work; money and employment; tourism; pest control; pollination; company from pets.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T01', true),
  ('P6_SCI_T02-Q1', 'P6', 'Science', 'Sound Energy', 16, 'What is sound, and how is it produced?', 'Sound is a form of energy produced when objects vibrate.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T02', true),
  ('P6_SCI_T02-Q2', 'P6', 'Science', 'Sound Energy', 17, 'Give any three natural and three artificial sources of sound.', 'Natural: thunder, wind, animal calls (also flowing water, the human voice). Artificial: a drum, a radio, a bell (also vehicles and machines).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T02', true),
  ('P6_SCI_T02-Q3', 'P6', 'Science', 'Sound Energy', 18, 'Give the difference between pitch and volume.', 'Pitch is how high or low a sound is and depends on frequency; volume is how loud or soft a sound is and depends on the size of the vibration.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T02', true),
  ('P6_SCI_T02-Q4', 'P6', 'Science', 'Sound Energy', 19, 'What is frequency, and how does it affect pitch?', 'Frequency is the number of vibrations in one second. The higher the frequency, the higher the pitch.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T02', true),
  ('P6_SCI_T02-Q5', 'P6', 'Science', 'Sound Energy', 20, 'In which medium does sound travel fastest, and why?', 'In a solid, because its particles are packed closely together and pass the vibrations on quickly.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T02', true),
  ('P6_SCI_T02-Q6', 'P6', 'Science', 'Sound Energy', 21, 'Why can sound not travel through a vacuum?', 'Because a vacuum has no particles (no medium) to carry the vibrations.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T02', true),
  ('P6_SCI_T02-Q7', 'P6', 'Science', 'Sound Energy', 22, 'Describe one experiment that shows sound travels through solids.', 'Place your ear flat on a desk while a friend scratches or taps the far end of the desk. The sound heard through the wood is louder and clearer than through the air, showing that solids carry sound well.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T02', true),
  ('P6_SCI_T02-Q8', 'P6', 'Science', 'Sound Energy', 23, 'What is an echo, and where can it be heard?', 'An echo is a sound heard again after bouncing off a hard surface. It can be heard in valleys, near cliffs, in empty halls and near high walls.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T02', true),
  ('P6_SCI_T02-Q9', 'P6', 'Science', 'Sound Energy', 24, 'Name the three main parts of the human ear.', 'The outer ear, middle ear and inner ear.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T02', true),
  ('P6_SCI_T02-Q10', 'P6', 'Science', 'Sound Energy', 25, 'Name the three small bones of the middle ear.', 'The hammer, anvil and stirrup.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T02', true),
  ('P6_SCI_T02-Q11', 'P6', 'Science', 'Sound Energy', 26, 'State the work of: the pinna, the ear drum, the cochlea, the auditory nerve.', 'Pinna — collects sound and directs it into the ear canal; ear drum — vibrates when sound hits it; cochlea — changes vibrations into nerve messages; auditory nerve — carries the messages to the brain.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T02', true),
  ('P6_SCI_T02-Q12', 'P6', 'Science', 'Sound Energy', 27, 'Which part of the ear keeps the body in balance?', 'The semi-circular canals.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T02', true),
  ('P6_SCI_T02-Q13', 'P6', 'Science', 'Sound Energy', 28, 'Name any four diseases or disorders of the ear.', 'Any four of: deafness, otitis media (ear infection), a perforated ear drum, ear wax blockage, foreign bodies in the ear, boils in the ear canal.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T02', true),
  ('P6_SCI_T02-Q14', 'P6', 'Science', 'Sound Energy', 29, 'Give any five ways of caring for the ear.', 'Any five of: never put sharp objects in the ear; clean only the outer ear with a damp cloth; avoid very loud noise and loud earphones; treat infections early; do not slap anyone on the ear; protect ears from cold; go for check-ups.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T02', true),
  ('P6_SCI_T02-Q15', 'P6', 'Science', 'Sound Energy', 30, 'Name the three types of musical instruments and give one example of each.', 'String — guitar or adungu; wind — flute or whistle; percussion — drum or xylophone.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T02', true),
  ('P6_SCI_T03-Q1', 'P6', 'Science', 'The Circulatory System', 31, 'Name the three parts of the circulatory system.', 'The heart, the blood vessels and the blood.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T03', true),
  ('P6_SCI_T03-Q2', 'P6', 'Science', 'The Circulatory System', 32, 'Where is the heart found, and what protects it?', 'In the chest, slightly to the left, protected by the ribs (and the breastbone).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T03', true),
  ('P6_SCI_T03-Q3', 'P6', 'Science', 'The Circulatory System', 33, 'Name the four chambers of the heart and state the work of each.', 'Right atrium — receives blood without oxygen from the body; right ventricle — pumps it to the lungs; left atrium — receives blood with oxygen from the lungs; left ventricle — pumps it to the whole body.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T03', true),
  ('P6_SCI_T03-Q4', 'P6', 'Science', 'The Circulatory System', 34, 'Why does the left ventricle have the thickest wall?', 'Because it pumps blood to the whole body, which needs much greater force than pumping to the lungs.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T03', true),
  ('P6_SCI_T03-Q5', 'P6', 'Science', 'The Circulatory System', 35, 'What is the work of the valves in the heart?', 'They stop blood from flowing backwards.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T03', true),
  ('P6_SCI_T03-Q6', 'P6', 'Science', 'The Circulatory System', 36, 'Name the three types of blood vessels and give one difference between arteries and veins.', 'Arteries, veins and capillaries. Arteries carry blood away from the heart with thick elastic walls at high pressure, while veins carry blood back to the heart, have thinner walls and contain valves.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T03', true),
  ('P6_SCI_T03-Q7', 'P6', 'Science', 'The Circulatory System', 37, 'Which artery carries blood without oxygen, and which vein carries blood with oxygen?', 'The pulmonary artery carries blood without oxygen; the pulmonary vein carries blood with oxygen.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T03', true),
  ('P6_SCI_T03-Q8', 'P6', 'Science', 'The Circulatory System', 38, 'Name the four parts of blood and give the work of each.', 'Plasma — carries food, water, salts and waste; red blood cells — carry oxygen; white blood cells — fight germs; platelets — help the blood to clot.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T03', true),
  ('P6_SCI_T03-Q9', 'P6', 'Science', 'The Circulatory System', 39, 'Name the four blood groups.', 'A, B, AB and O.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T03', true),
  ('P6_SCI_T03-Q10', 'P6', 'Science', 'The Circulatory System', 40, 'Give any four functions of blood.', 'Any four of: transporting oxygen; transporting food and water; carrying waste to the excretory organs; fighting germs; clotting to stop bleeding; spreading heat round the body.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T03', true),
  ('P6_SCI_T03-Q11', 'P6', 'Science', 'The Circulatory System', 41, 'Name any four diseases or disorders of the circulatory system.', 'Any four of: anaemia, sickle cell disease, leukaemia, high blood pressure, heart attack, haemophilia, varicose veins.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T03', true),
  ('P6_SCI_T03-Q12', 'P6', 'Science', 'The Circulatory System', 42, 'Give three ways in which HIV can be spread through blood, and three ways of preventing this.', 'Spread: transfusion of untested blood; sharing needles or syringes; sharing razor blades or other skin-cutting instruments (also mother to child). Prevention: use only screened blood; use sterile single-use needles; never share razor blades or sharp instruments (and mothers who are HIV positive should follow medical advice).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T03', true),
  ('P6_SCI_T03-Q13', 'P6', 'Science', 'The Circulatory System', 43, 'Give any five ways of increasing the volume of blood in the body.', 'Any five of: eat iron-rich foods such as dodo, nakati, liver, beans and meat; eat fruits rich in vitamin C; deworm regularly; sleep under a mosquito net; treat wounds and bleeding quickly; exercise; rest well; have a transfusion of screened blood in serious cases.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T03', true),
  ('P6_SCI_T03-Q14', 'P6', 'Science', 'The Circulatory System', 44, 'Why should blood for transfusion be tested first?', 'To make sure it is the right blood group for the patient and that it is free from germs and infections such as HIV, hepatitis and syphilis, so that the transfusion helps instead of harming.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T03', true),
  ('P6_SCI_T03-Q15', 'P6', 'Science', 'The Circulatory System', 45, 'Trace the path of blood from the body back to the body, naming the chambers and the lungs.', 'Body → right atrium → right ventricle → lungs (to get oxygen) → left atrium → left ventricle → back to the body.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T03', true),
  ('P6_SCI_T04-Q1', 'P6', 'Science', 'Alcohol, Smoking and Drugs in Society', 46, 'What is alcoholism? Who is an alcoholic?', 'Alcoholism is the condition of being unable to stop taking alcohol — addiction to alcohol. An alcoholic is a person who is addicted to alcohol.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T04', true),
  ('P6_SCI_T04-Q2', 'P6', 'Science', 'Alcohol, Smoking and Drugs in Society', 47, 'Give any four effects of alcoholism on the individual.', 'Any four of: damage to the liver, stomach and brain; loss of memory and poor judgement; accidents and injuries; loss of job and poverty; poor health, malnutrition and early death.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T04', true),
  ('P6_SCI_T04-Q3', 'P6', 'Science', 'Alcohol, Smoking and Drugs in Society', 48, 'Give any three effects of alcoholism on the family and three on the community.', 'Family: money wasted instead of buying food and paying fees; quarrels and violence; children dropping out of school; neglect of the family. Community: crime and insecurity; road accidents; loss of a productive workforce; extra burden on hospitals and police. (Any three each.)', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T04', true),
  ('P6_SCI_T04-Q4', 'P6', 'Science', 'Alcohol, Smoking and Drugs in Society', 49, 'Name any three harmful substances found in tobacco smoke and what each does.', 'Nicotine — causes addiction; tar — causes cancer; carbon monoxide — reduces the oxygen carried by the blood.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T04', true),
  ('P6_SCI_T04-Q5', 'P6', 'Science', 'Alcohol, Smoking and Drugs in Society', 50, 'Give the difference between active and passive smoking.', 'Active smoking is smoking a cigarette yourself; passive smoking is breathing in the smoke of somebody else who is smoking.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T04', true),
  ('P6_SCI_T04-Q6', 'P6', 'Science', 'Alcohol, Smoking and Drugs in Society', 51, 'Why is passive smoking dangerous, especially for children and pregnant mothers?', 'Because passive smokers breathe the same harmful substances and suffer the same diseases, and children''s lungs and unborn babies are still developing, so the harm is greater — it can cause coughs, chest infections, poor growth and low birth weight.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T04', true),
  ('P6_SCI_T04-Q7', 'P6', 'Science', 'Alcohol, Smoking and Drugs in Society', 52, 'Give any four effects of smoking on a person''s health.', 'Any four of: lung cancer; chronic cough and bronchitis; tuberculosis; heart disease; stained teeth and bad breath; poor appetite; addiction.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T04', true),
  ('P6_SCI_T04-Q8', 'P6', 'Science', 'Alcohol, Smoking and Drugs in Society', 53, 'What are essential drugs? Give any four examples.', 'Essential drugs are the medicines a community most needs and which should always be available at a health centre. Examples: ORS, paracetamol, anti-malarial tablets, antibiotics, deworming tablets, vaccines (any four).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T04', true),
  ('P6_SCI_T04-Q9', 'P6', 'Science', 'Alcohol, Smoking and Drugs in Society', 54, 'Give any four characteristics of good drugs.', 'Any four of: within the expiry date; properly sealed and labelled; from a licensed health centre or pharmacy; with the correct name, dose and instructions; not discoloured, crushed or damp.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T04', true),
  ('P6_SCI_T04-Q10', 'P6', 'Science', 'Alcohol, Smoking and Drugs in Society', 55, 'Give any five rules for storing drugs safely in a home.', 'Any five of: keep them in a cool, dry, dark place; keep them in the original labelled container; close them tightly; keep them out of reach of children, preferably locked; do not store them with food or paraffin; check the expiry date; destroy or return expired drugs safely.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T04', true),
  ('P6_SCI_T04-Q11', 'P6', 'Science', 'Alcohol, Smoking and Drugs in Society', 56, 'Give the difference between drug abuse and drug misuse, with one example of each.', 'Drug abuse is using a drug for a purpose it was not meant for, for example sniffing petrol. Drug misuse is using a proper medicine wrongly, for example taking the wrong dose or using somebody else''s prescription.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T04', true),
  ('P6_SCI_T04-Q12', 'P6', 'Science', 'Alcohol, Smoking and Drugs in Society', 57, 'What is drug dependence?', 'Drug dependence is when the body or the mind can no longer do without the drug, so the person suffers when he or she stops taking it.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T04', true),
  ('P6_SCI_T04-Q13', 'P6', 'Science', 'Alcohol, Smoking and Drugs in Society', 58, 'Name any four commonly abused substances.', 'Any four of: alcohol, tobacco, marijuana (njaga), khat (mairungi), petrol or glue fumes, cocaine, heroin, wrongly used sleeping tablets.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T04', true),
  ('P6_SCI_T04-Q14', 'P6', 'Science', 'Alcohol, Smoking and Drugs in Society', 59, 'Give any five factors that lead young people into alcoholism, smoking or drug abuse.', 'Any five of: peer pressure; curiosity; idleness and too much free time; copying parents or film and music stars; advertising; frustration and family problems; easy availability; lack of guidance.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T04', true),
  ('P6_SCI_T04-Q15', 'P6', 'Science', 'Alcohol, Smoking and Drugs in Society', 60, 'Name any five life skills that help a young person to refuse drugs, and explain one of them.', 'Any five of: assertiveness, peer pressure resistance, decision-making, critical thinking, self-esteem, coping with stress, effective communication, using free time well. Assertiveness, for example, is the ability to say NO firmly and to repeat it without fear or apology, and to walk away from the situation.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T04', true),
  ('P6_SCI_T05-Q1', 'P6', 'Science', 'Classification of Plants', 61, 'Give the difference between flowering and non-flowering plants, with two examples of each.', 'Flowering plants produce flowers and seeds, for example maize and mango; non-flowering plants do not produce flowers, for example ferns and pine.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T05', true),
  ('P6_SCI_T05-Q2', 'P6', 'Science', 'Classification of Plants', 62, 'Name the three groups of non-flowering plants and give one example of each.', 'Spore-bearing plants — fern; conifers — pine; algae — spirogyra (or seaweed).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T05', true),
  ('P6_SCI_T05-Q3', 'P6', 'Science', 'Classification of Plants', 63, 'Give three differences between legumes and cereals.', 'Legumes: seeds in pods, two seed leaves, root nodules that add nitrogen, rich in protein. Cereals: grasses grown for grain, one seed leaf, fibrous roots, rich in carbohydrates. (Any three pairs.)', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T05', true),
  ('P6_SCI_T05-Q4', 'P6', 'Science', 'Classification of Plants', 64, 'Why is planting legumes good for the soil?', 'Because their root nodules contain bacteria that add nitrogen to the soil, making it fertile again for the next crop.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T05', true),
  ('P6_SCI_T05-Q5', 'P6', 'Science', 'Classification of Plants', 65, 'Name the male and the female parts of a flower and state the work of each.', 'The stamen (anther and filament) is the male part and makes pollen; the pistil (stigma, style and ovary) is the female part and receives pollen and holds the ovules.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T05', true),
  ('P6_SCI_T05-Q6', 'P6', 'Science', 'Classification of Plants', 66, 'What is pollination, and what happens to the ovary after fertilisation?', 'Pollination is the transfer of pollen from the anther to the stigma. After fertilisation the ovary becomes the fruit and the ovules become seeds.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T05', true),
  ('P6_SCI_T05-Q7', 'P6', 'Science', 'Classification of Plants', 67, 'What is seed dispersal, and give any four reasons why it is necessary?', 'Seed dispersal is the scattering of seeds away from the parent plant. Reasons: to avoid overcrowding; to reduce competition for water, light and food; to spread the plant to new areas; to reduce the spread of pests and diseases (any four).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T05', true),
  ('P6_SCI_T05-Q8', 'P6', 'Science', 'Classification of Plants', 68, 'Name the five agents of seed dispersal.', 'Wind, water, animals (and birds), explosive mechanism, and people.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T05', true),
  ('P6_SCI_T05-Q9', 'P6', 'Science', 'Classification of Plants', 69, 'Give the features of a seed dispersed by wind and one dispersed by animals.', 'Wind: the seed is light and has wings, hairs or a parachute. Animals: the fruit is sweet and fleshy so it is eaten, or the seed has hooks that stick to fur and clothes.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T05', true),
  ('P6_SCI_T05-Q10', 'P6', 'Science', 'Classification of Plants', 70, 'What is plant propagation? Name its two types.', 'Plant propagation is the way new plants are produced from old ones. Its two types are sexual (by seeds) and vegetative (asexual).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T05', true),
  ('P6_SCI_T05-Q11', 'P6', 'Science', 'Classification of Plants', 71, 'Name any six methods of vegetative propagation, with one example of each.', 'Any six: cuttings — cassava; suckers — banana; tubers — Irish potato; bulbs — onion; rhizomes — ginger; runners — grass; grafting — mango; layering — guava.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T05', true),
  ('P6_SCI_T05-Q12', 'P6', 'Science', 'Classification of Plants', 72, 'Give two advantages and two disadvantages of vegetative propagation.', 'Advantages: the new plant is exactly like the parent and it matures faster. Disadvantages: diseases are passed on easily and there is no variety among the plants.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T05', true),
  ('P6_SCI_T05-Q13', 'P6', 'Science', 'Classification of Plants', 73, 'Give any six economic values of plants.', 'Any six of: food; cash crops and employment; timber and poles; firewood and charcoal; medicine; raw materials for industries; fodder for animals; shade and windbreaks; protection of the environment and supply of oxygen; tourism.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T05', true),
  ('P6_SCI_T05-Q14', 'P6', 'Science', 'Classification of Plants', 74, 'Why do farmers plant beans in a garden where maize was grown the season before?', 'Because the beans are a legume whose root nodules add nitrogen to the soil, restoring the fertility that the maize used up. This is crop rotation.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T05', true),
  ('P6_SCI_T05-Q15', 'P6', 'Science', 'Classification of Plants', 75, 'Give one plant grown from each of: cuttings, suckers, bulbs, rhizomes, tubers.', 'Cuttings — cassava; suckers — banana; bulbs — onion; rhizomes — ginger; tubers — Irish potato (or sweet potato).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T05', true),
  ('P6_SCI_T06-Q1', 'P6', 'Science', 'Keeping Cattle', 76, 'Name the four types of cattle and what each is kept for.', 'Dairy — milk; beef — meat; dual-purpose — both milk and meat; work (draught) — ploughing and pulling carts.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T06', true),
  ('P6_SCI_T06-Q2', 'P6', 'Science', 'Keeping Cattle', 77, 'Give the difference between indigenous and exotic breeds, with two examples of each.', 'Indigenous breeds have always been in the country, for example Ankole long-horned and Zebu; exotic breeds were brought from other countries, for example Friesian and Jersey.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T06', true),
  ('P6_SCI_T06-Q3', 'P6', 'Science', 'Keeping Cattle', 78, 'Give two advantages of indigenous breeds and two of exotic breeds.', 'Indigenous: resist diseases and heat, and can walk long distances for pasture and water. Exotic: give much more milk or meat, and mature faster.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T06', true),
  ('P6_SCI_T06-Q4', 'P6', 'Science', 'Keeping Cattle', 79, 'Name any six external features of a cow.', 'Any six of: horns, eyes, ears, muzzle, dewlap, hump, udder with teats, tail, hooves, hide, back, flank.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T06', true),
  ('P6_SCI_T06-Q5', 'P6', 'Science', 'Keeping Cattle', 80, 'Give three differences between a cow and a bull.', 'A cow has an udder with four teats while a bull has none; a bull has a larger head and thicker neck and shoulders; a bull is usually stronger and fiercer, while the cow is gentler and produces milk.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T06', true),
  ('P6_SCI_T06-Q6', 'P6', 'Science', 'Keeping Cattle', 81, 'Define: heifer, steer, calf.', 'Heifer — a young female that has not yet calved; steer (ox) — a castrated male; calf — the young one of cattle.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T06', true),
  ('P6_SCI_T06-Q7', 'P6', 'Science', 'Keeping Cattle', 82, 'Name any four methods of grazing cattle.', 'Any four of: free range, paddocking, tethering, zero grazing, strip grazing.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T06', true),
  ('P6_SCI_T06-Q8', 'P6', 'Science', 'Keeping Cattle', 83, 'Give three advantages of zero grazing.', 'Any three of: it suits a small piece of land; the milk and the animal stay clean; manure is easily collected; the animal uses less energy so it gives more milk; it is easy to control diseases and feeding.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T06', true),
  ('P6_SCI_T06-Q9', 'P6', 'Science', 'Keeping Cattle', 84, 'Name any five feeds given to cattle.', 'Any five of: pasture grasses, fodder such as elephant grass, legumes such as calliandra, crop residues, concentrates such as dairy meal, mineral salt licks, and clean water.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T06', true),
  ('P6_SCI_T06-Q10', 'P6', 'Science', 'Keeping Cattle', 85, 'Give any five qualities of a good cattle shed.', 'Any five of: spacious, dry, well ventilated, easy to clean, with a concrete or sloping floor, a good roof, feeding and watering places, a calf pen, a milking area and a crush.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T06', true),
  ('P6_SCI_T06-Q11', 'P6', 'Science', 'Keeping Cattle', 86, 'What is the gestation period of a cow? What is calving?', 'The gestation period is about nine months (280 days). Calving is the act of giving birth to a calf.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T06', true),
  ('P6_SCI_T06-Q12', 'P6', 'Science', 'Keeping Cattle', 87, 'What is colostrum, and why must the calf get it?', 'Colostrum is the first thick yellow milk produced after calving. The calf must get it because it is rich in antibodies that protect it from disease, and in nutrients for a good start.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T06', true),
  ('P6_SCI_T06-Q13', 'P6', 'Science', 'Keeping Cattle', 88, 'Give any three advantages of artificial insemination.', 'Any three of: a farmer can use a very good bull without keeping one; it prevents diseases spread by mating; one bull can serve very many cows; it improves the breed quickly; it is cheaper than keeping a bull.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T06', true),
  ('P6_SCI_T06-Q14', 'P6', 'Science', 'Keeping Cattle', 89, 'Give any six rules of clean milking.', 'Any six of: milk at the same time daily; wash hands and the udder with clean warm water and dry them; use clean dry metal containers; use the full-hand method; milk quickly and completely; keep the shed clean; sieve and cool the milk at once; a sick person or sick cow must not supply milk.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T06', true),
  ('P6_SCI_T06-Q15', 'P6', 'Science', 'Keeping Cattle', 90, 'Name any five milk products.', 'Any five of: ghee, butter, yoghurt, cheese, sour milk, cream, powdered milk, ice cream.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T06', true),
  ('P6_SCI_T06-Q16', 'P6', 'Science', 'Keeping Cattle', 91, 'Name any four cattle pests and the harm each causes.', 'Any four: ticks — suck blood and spread East Coast fever; tsetse flies — spread nagana; worms — cause anaemia and poor growth; lice and mites — cause irritation and wounds.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T06', true),
  ('P6_SCI_T06-Q17', 'P6', 'Science', 'Keeping Cattle', 92, 'Name any four cattle diseases and one way of controlling each.', 'Any four, for example: foot and mouth disease — vaccination and quarantine; East Coast fever — spraying or dipping against ticks; nagana — control tsetse flies and clear bush; mastitis — clean milking and treatment; anthrax — vaccination and never opening the carcass.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T06', true),
  ('P6_SCI_T06-Q18', 'P6', 'Science', 'Keeping Cattle', 93, 'Give any five practices that harm cattle.', 'Any five of: beating and overworking; rough or over-milking; tethering with no shade or water; overstocking and overgrazing; using dirty instruments for dehorning or castration; burning pasture; using wrong or expired drugs.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T06', true),
  ('P6_SCI_T06-Q19', 'P6', 'Science', 'Keeping Cattle', 94, 'Give any six steps in starting a livestock farm.', 'Any six of: choose a suitable site; decide the type of cattle and the system; get capital and plan; prepare land, pasture and fencing; build the shed and crush; buy healthy stock; arrange feeds and water; register with the veterinary officer; keep records; find a market.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T06', true),
  ('P6_SCI_T06-Q20', 'P6', 'Science', 'Keeping Cattle', 95, 'Why should a farmer keep records on a cattle farm?', 'Because records show which cows produce most milk, when each was served and is due to calve, what treatment was given, and how much money came in and went out — so the farmer can plan, breed better animals and know whether the farm is making a profit.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T06', true),
  ('P6_SCI_T07-Q1', 'P6', 'Science', 'Resources in the Environment', 96, 'What is a resource? Give three living and three non-living resources.', 'A resource is anything in the environment that people use to satisfy their needs. Living: plants, animals, fish (also birds, insects, people). Non-living: soil, water, air (also minerals, sunlight, rocks).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T07', true),
  ('P6_SCI_T07-Q2', 'P6', 'Science', 'Resources in the Environment', 97, 'Why are human beings called a resource?', 'Because people provide labour, skills, ideas and leadership that are needed to use all the other resources and to develop the country.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T07', true),
  ('P6_SCI_T07-Q3', 'P6', 'Science', 'Resources in the Environment', 98, 'What is harvesting? Give the way each of these is harvested: fish, timber, salt, minerals.', 'Harvesting is collecting a resource from the environment for use. Fish — nets, hooks and traps; timber — felling trees and sawing; salt — evaporating water from salt lakes such as Katwe; minerals — mining, quarrying, drilling or panning.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T07', true),
  ('P6_SCI_T07-Q4', 'P6', 'Science', 'Resources in the Environment', 99, 'Give any five good harvesting practices.', 'Any five of: take only what is needed; use the right tools and methods; leave young plants, fish and animals to grow; avoid poison, explosives and undersized nets; replant after cutting trees; avoid harvesting in the breeding season; store the harvest well.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T07', true),
  ('P6_SCI_T07-Q5', 'P6', 'Science', 'Resources in the Environment', 100, 'Give any four uses of water and four uses of soil.', 'Water: drinking, cooking and washing, irrigation, fishing, transport, hydro-electric power (any four). Soil: growing crops, making bricks, making pots, building, holding plant roots (any four).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T07', true),
  ('P6_SCI_T07-Q6', 'P6', 'Science', 'Resources in the Environment', 101, 'Give the difference between renewable and non-renewable resources.', 'Renewable resources can be replaced or never run out, such as sunlight and wind; non-renewable resources get used up and cannot be replaced, such as gold and petroleum.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T07', true),
  ('P6_SCI_T07-Q7', 'P6', 'Science', 'Resources in the Environment', 102, 'Classify these as renewable or non-renewable: sunlight, copper, wind, petroleum, forests.', 'Renewable: sunlight, wind, forests. Non-renewable: copper, petroleum.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T07', true),
  ('P6_SCI_T07-Q8', 'P6', 'Science', 'Resources in the Environment', 103, 'Why are plants and animals renewable only under certain conditions?', 'Because they can only replace themselves if they are given time and conditions to reproduce. If people cut trees or catch fish faster than they can reproduce, they are used up completely and may become extinct.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T07', true),
  ('P6_SCI_T07-Q9', 'P6', 'Science', 'Resources in the Environment', 104, 'What is meant by depletion of a resource? Give one example.', 'Depletion is using up a resource until very little is left, for example over-fishing on a lake until the fish stocks nearly disappear (or over-cutting of forests).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T07', true),
  ('P6_SCI_T07-Q10', 'P6', 'Science', 'Resources in the Environment', 105, 'What does it mean when an animal species is said to be extinct?', 'It means the species no longer exists anywhere — every member of it has died and it can never be brought back.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T07', true),
  ('P6_SCI_T07-Q11', 'P6', 'Science', 'Resources in the Environment', 106, 'What is conservation?', 'Conservation is protecting and using resources carefully so that they are not destroyed or used up.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T07', true),
  ('P6_SCI_T07-Q12', 'P6', 'Science', 'Resources in the Environment', 107, 'Give any five ways of conserving soil.', 'Any five of: mulching, terracing, contour ploughing, crop rotation, applying manure, planting cover crops, controlled grazing, planting trees.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T07', true),
  ('P6_SCI_T07-Q13', 'P6', 'Science', 'Resources in the Environment', 108, 'Give any four ways of conserving water.', 'Any four of: harvesting rain water, protecting springs and wetlands, avoiding pollution, closing taps, careful irrigation, repairing leaking pipes.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T07', true),
  ('P6_SCI_T07-Q14', 'P6', 'Science', 'Resources in the Environment', 109, 'Give any four ways of conserving forests and four ways of protecting wild animals and fish.', 'Forests: afforestation, reafforestation, agroforestry, energy-saving stoves, forest reserves (any four). Animals and fish: game parks and sanctuaries, laws against poaching, closed fishing seasons, correct net sizes, fish farming (any four).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T07', true),
  ('P6_SCI_T07-Q15', 'P6', 'Science', 'Resources in the Environment', 110, 'Give any five reasons why resources must be conserved.', 'Any five of: so that resources last for future generations; to keep the environment healthy; to keep soil fertile and rainfall reliable; to protect wildlife and tourism; to avoid famine and poverty; to prevent conflicts over scarce resources.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T07', true),
  ('P6_SCI_T08-Q1', 'P6', 'Science', 'The Respiratory System', 111, 'Give the difference between breathing and respiration.', 'Breathing is simply taking in and giving out air, while respiration is the process by which the body breaks down food to release energy inside the cells.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T08', true),
  ('P6_SCI_T08-Q2', 'P6', 'Science', 'The Respiratory System', 112, 'Name any six organs of the respiratory system.', 'Any six of: nose, pharynx, epiglottis, larynx, trachea, bronchi, bronchioles, alveoli, lungs, diaphragm.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T08', true),
  ('P6_SCI_T08-Q3', 'P6', 'Science', 'The Respiratory System', 113, 'State the work of: the nose, the epiglottis, the trachea, the alveoli, the diaphragm.', 'Nose — takes in air and filters, warms and moistens it; epiglottis — closes the windpipe when swallowing; trachea — carries air to the lungs; alveoli — where oxygen enters the blood and carbon dioxide leaves; diaphragm — the muscle that flattens and relaxes to help breathing.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T08', true),
  ('P6_SCI_T08-Q4', 'P6', 'Science', 'The Respiratory System', 114, 'Trace the path taken by air from outside the body to the blood.', 'Nose → pharynx → larynx → trachea → bronchi → bronchioles → alveoli → blood.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T08', true),
  ('P6_SCI_T08-Q5', 'P6', 'Science', 'The Respiratory System', 115, 'Why is it better to breathe through the nose than through the mouth?', 'Because the nose has hairs and mucus that trap dust and germs, and it warms and moistens the air before it reaches the lungs; the mouth does none of these.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T08', true),
  ('P6_SCI_T08-Q6', 'P6', 'Science', 'The Respiratory System', 116, 'Describe what happens to the diaphragm and the ribs when a person breathes in.', 'The diaphragm flattens and moves downwards, the ribs move upwards and outwards, the chest cavity increases in size and air rushes into the lungs.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T08', true),
  ('P6_SCI_T08-Q7', 'P6', 'Science', 'The Respiratory System', 117, 'Give three differences between inhaled and exhaled air.', 'Any three of: inhaled air has more oxygen (21% against 16%); exhaled air has much more carbon dioxide (about 4% against 0.03%); exhaled air has more water vapour; exhaled air is warmer.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T08', true),
  ('P6_SCI_T08-Q8', 'P6', 'Science', 'The Respiratory System', 118, 'Describe one experiment that shows exhaled air contains carbon dioxide.', 'Breathe out through a straw into lime water. The lime water turns milky, showing that carbon dioxide is present. (Comparing with air blown in by a pump shows the difference.)', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T08', true),
  ('P6_SCI_T08-Q9', 'P6', 'Science', 'The Respiratory System', 119, 'Describe one experiment that shows exhaled air contains water vapour.', 'Breathe onto a cold mirror or glass. Tiny drops of water form on it, showing that exhaled air contains water vapour.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T08', true),
  ('P6_SCI_T08-Q10', 'P6', 'Science', 'The Respiratory System', 120, 'Write the word equation for respiration.', 'Food (glucose) + oxygen → energy + carbon dioxide + water', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T08', true),
  ('P6_SCI_T08-Q11', 'P6', 'Science', 'The Respiratory System', 121, 'Give any four uses of the energy released during respiration.', 'Any four of: movement and work; growth and repair of the body; keeping the body warm; the beating of the heart and the working of other organs; thinking; digestion.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T08', true),
  ('P6_SCI_T08-Q12', 'P6', 'Science', 'The Respiratory System', 122, 'Name any five diseases of the respiratory system.', 'Any five of: tuberculosis, pneumonia, bronchitis, asthma, the common cold and flu, whooping cough, lung cancer, diphtheria.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T08', true),
  ('P6_SCI_T08-Q13', 'P6', 'Science', 'The Respiratory System', 123, 'Give the cause and two signs of tuberculosis.', 'Tuberculosis is caused by bacteria spread through coughing and sneezing by an infected person. Signs: a cough lasting more than two weeks, chest pain, weight loss, night sweats, fever (any two).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T08', true),
  ('P6_SCI_T08-Q14', 'P6', 'Science', 'The Respiratory System', 124, 'Give any six ways of keeping the respiratory system healthy.', 'Any six of: do not smoke and avoid other people''s smoke; keep rooms well ventilated; avoid dust and cooking smoke; cover the mouth when coughing; immunise children; eat a balanced diet; exercise regularly; breathe through the nose; avoid overcrowded rooms; treat coughs and colds early; plant trees.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T08', true),
  ('P6_SCI_T08-Q15', 'P6', 'Science', 'The Respiratory System', 125, 'How does the circulatory system help the respiratory system?', 'The blood, especially the red blood cells, carries oxygen from the alveoli to every cell of the body, and carries the waste carbon dioxide back to the lungs to be breathed out. Without the circulatory system, the oxygen would never reach the cells.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T08', true),
  ('P6_SCI_T09-Q1', 'P6', 'Science', 'Science at Home and in Our Community', 126, 'Give the difference between clean water and safe water.', 'Clean water has no dirt that you can see, while safe water is free from germs and harmful substances and can be drunk without causing disease. Water can look clean and still be unsafe.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T09', true),
  ('P6_SCI_T09-Q2', 'P6', 'Science', 'Science at Home and in Our Community', 127, 'Name any five impurities found in water and where each comes from.', 'Any five, for example: human wastes — from poor latrines and open defecation; animal wastes — from animals at the water source; fertilisers and pesticides — from gardens; oils and chemicals — from factories and garages; silt and leaves — washed in by rain; rubbish and polythene — from homes.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T09', true),
  ('P6_SCI_T09-Q3', 'P6', 'Science', 'Science at Home and in Our Community', 128, 'Name any four diseases caused by drinking unsafe water.', 'Any four of: cholera, typhoid, dysentery, diarrhoea, bilharzia, worms, hepatitis.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T09', true),
  ('P6_SCI_T09-Q4', 'P6', 'Science', 'Science at Home and in Our Community', 129, 'Name five methods of making water safe for drinking.', 'Boiling, filtering, treating with chemicals, distilling and decanting (also solar disinfection).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T09', true),
  ('P6_SCI_T09-Q5', 'P6', 'Science', 'Science at Home and in Our Community', 130, 'Describe how water is made safe by decanting.', 'The dirty water is left to stand undisturbed in a container until the heavy particles settle at the bottom. The clear water on top is then poured off carefully into another clean container, leaving the sediment behind.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T09', true),
  ('P6_SCI_T09-Q6', 'P6', 'Science', 'Science at Home and in Our Community', 131, 'Why is boiling the commonest method used in homes?', 'Because it is cheap and easy — every home has a fire — and it kills the germs that cause disease, needing no special chemicals or equipment.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T09', true),
  ('P6_SCI_T09-Q7', 'P6', 'Science', 'Science at Home and in Our Community', 132, 'Which method gives the purest water, and why?', 'Distillation, because boiling turns the water into steam, leaving germs, salts and other dissolved substances behind; the steam is then cooled back into very pure water.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T09', true),
  ('P6_SCI_T09-Q8', 'P6', 'Science', 'Science at Home and in Our Community', 133, 'Give the correct order of treating very dirty water and say why that order is used.', 'First decant or filter to remove the dirt you can see, then boil or treat to kill the germs, then store in a clean covered container. Filtering first is important because dirt and solid matter can protect germs from the treatment and make chemicals less effective.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T09', true),
  ('P6_SCI_T09-Q9', 'P6', 'Science', 'Science at Home and in Our Community', 134, 'Give any four rules for storing drinking water safely.', 'Any four of: use a clean covered container; use a tap or long-handled cup so hands do not enter; never mix treated with untreated water; clean the container regularly; keep it away from animals and small children.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T09', true),
  ('P6_SCI_T09-Q10', 'P6', 'Science', 'Science at Home and in Our Community', 135, 'Give any five ways of protecting a water source.', 'Any five of: fence the source; build a drainage channel; keep latrines at least 30 m away and downhill; do not wash clothes or bathe at the source; do not water animals there; do not dig or farm next to it; plant grass around it.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T09', true),
  ('P6_SCI_T09-Q11', 'P6', 'Science', 'Science at Home and in Our Community', 136, 'Name any four plant materials used to make salt.', 'Any four of: dry banana peelings, banana stems, bean stalks, millet stalks, papyrus reeds, water-lily plants.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T09', true),
  ('P6_SCI_T09-Q12', 'P6', 'Science', 'Science at Home and in Our Community', 137, 'Describe, in steps, how salt is made from plant materials.', 'Dry the plant material → burn it into ash → put the ash in a container or funnel-shaped basket lined with grass → pour clean water slowly through the ash (leaching) → collect the filtrate → boil it until all the water evaporates → the solid salt is left behind.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T09', true),
  ('P6_SCI_T09-Q13', 'P6', 'Science', 'Science at Home and in Our Community', 138, 'Which three science processes are shown when making salt from plants?', 'Dissolving, filtering and evaporation.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T09', true),
  ('P6_SCI_T09-Q14', 'P6', 'Science', 'Science at Home and in Our Community', 139, 'Give any six steps followed when washing clothes at home.', 'Any six of: sort the clothes; empty the pockets and shake off dust; soak them in soapy water; wash by rubbing or brushing the dirty parts; rinse two or three times; hang them in the sun to dry; iron them; fold and store them cleanly.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T09', true),
  ('P6_SCI_T09-Q15', 'P6', 'Science', 'Science at Home and in Our Community', 140, 'Give any four reasons why clothes should be washed and ironed.', 'Any four of: to remove dirt, sweat and bad smell; to kill germs and prevent skin diseases; to kill jiggers and lice by ironing; to make the clothes last longer; to look smart and keep self-respect.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T09', true),
  ('P6_SCI_T10-Q1', 'P6', 'Science', 'Accidents and First Aid', 141, 'What is first aid, and who is a first aider?', 'First aid is the immediate help given to an injured or suddenly sick person before a health worker arrives or before the person reaches hospital. A first aider is the person who gives it.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T10', true),
  ('P6_SCI_T10-Q2', 'P6', 'Science', 'Accidents and First Aid', 142, 'Give any four aims of first aid.', 'Any four of: to save life; to prevent the injury from getting worse; to relieve pain; to promote recovery; to get the person quickly to proper medical care.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T10', true),
  ('P6_SCI_T10-Q3', 'P6', 'Science', 'Accidents and First Aid', 143, 'Give any five qualities of a good first aider.', 'Any five of: calm and confident; quick but careful; clean; kind and comforting; observant; knows his or her limits; sends for help early.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T10', true),
  ('P6_SCI_T10-Q4', 'P6', 'Science', 'Accidents and First Aid', 144, 'Name any eight items found in a first-aid kit.', 'Any eight of: cotton wool, bandages, gauze, plaster, scissors, antiseptic, gloves, a thermometer, safety pins, clean water, a torch, ORS, a splint, a notebook and pen.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T10', true),
  ('P6_SCI_T10-Q5', 'P6', 'Science', 'Accidents and First Aid', 145, 'Give the difference between a burn and a scald, with one cause of each.', 'A burn is caused by dry heat, for example fire or a hot iron; a scald is caused by moist heat, for example hot water or steam.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T10', true),
  ('P6_SCI_T10-Q6', 'P6', 'Science', 'Accidents and First Aid', 146, 'Give the steps of first aid for a burn.', 'Remove the person from the source of heat (switching off electricity if needed) → cool the part with clean cool water for 10–20 minutes → remove tight clothing near the burn before swelling → cover with a clean dry non-fluffy cloth → give fluids if the person is fully awake → take them to a health centre if the burn is large, deep or on the face or hands.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T10', true),
  ('P6_SCI_T10-Q7', 'P6', 'Science', 'Accidents and First Aid', 147, 'Name any four things that should never be put on a burn.', 'Any four of: cow dung, engine oil, paraffin, mud, butter, toothpaste, ash, ice.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T10', true),
  ('P6_SCI_T10-Q8', 'P6', 'Science', 'Accidents and First Aid', 148, 'Give any four ways of preventing burns and scalds at home.', 'Any four of: keep children away from the fireplace and kitchen; turn saucepan handles inwards; put out fires properly; lock away paraffin, petrol and matches; do not overload sockets; put out candles before sleeping; keep hot drinks away from table edges.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T10', true),
  ('P6_SCI_T10-Q9', 'P6', 'Science', 'Accidents and First Aid', 149, 'What is fever, and what is the normal body temperature?', 'Fever is a body temperature higher than normal. The normal body temperature is about 37 °C.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T10', true),
  ('P6_SCI_T10-Q10', 'P6', 'Science', 'Accidents and First Aid', 150, 'Give the first aid for a child with a high fever.', 'Move the child to a cool airy place → remove heavy clothing → sponge with lukewarm water → give plenty of fluids → give the correct dose of fever medicine if available → take the child for a malaria test and treatment quickly.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T10', true),
  ('P6_SCI_T10-Q11', 'P6', 'Science', 'Accidents and First Aid', 151, 'What are convulsions? Give three causes.', 'Convulsions are sudden uncontrollable jerking of the body. Causes: very high fever in a child, epilepsy, cerebral malaria or meningitis (any three).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T10', true),
  ('P6_SCI_T10-Q12', 'P6', 'Science', 'Accidents and First Aid', 152, 'Give any five steps of first aid for a person having convulsions, and two things you must not do.', 'Do: stay calm and call for help; lay the person on the floor on their side away from fire, water and sharp objects; loosen tight clothing; put something soft under the head; after the fit, keep them on their side and take them to a health centre. Do not: put anything in the mouth; hold the person down or pour cold water on them.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T10', true),
  ('P6_SCI_T10-Q13', 'P6', 'Science', 'Accidents and First Aid', 153, 'Give the first aid for a person who has nearly drowned, and say why a weak swimmer should not jump in.', 'Reach out to the person with a stick, rope or floating object; once out, lay them on their side so water drains; check breathing; keep them warm; if they are not breathing, give rescue breathing if trained and keep calling for help; take them to hospital. A weak swimmer should not jump in because the drowning person panics and clings, and both can drown.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T10', true),
  ('P6_SCI_T10-Q14', 'P6', 'Science', 'Accidents and First Aid', 154, 'Give any five ways of preventing drowning.', 'Any five of: learn to swim; never swim alone or in flooded rivers; do not overload boats and wear life jackets; never play near wells or tanks; cover wells and tanks; watch small children near any water; do not swim after a heavy meal or in a storm.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T10', true),
  ('P6_SCI_T10-Q15', 'P6', 'Science', 'Accidents and First Aid', 155, 'What is fainting? Give three causes and the first aid given.', 'Fainting is a short loss of consciousness caused by too little blood reaching the brain. Causes: standing too long in the sun, hunger, tiredness, shock or fear (any three). First aid: lay the person flat in a cool airy place, raise the legs, loosen tight clothing, allow fresh air, sponge the face, and give water when they wake.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T10', true),
  ('P6_SCI_T10-Q16', 'P6', 'Science', 'Accidents and First Aid', 156, 'Why is a person who has fainted made to lie down with the legs raised?', 'Because raising the legs helps blood flow back to the brain, which is what was lacking, so the person recovers quickly.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T10', true),
  ('P6_SCI_T10-Q17', 'P6', 'Science', 'Accidents and First Aid', 157, 'What is a foreign body? Give the first aid for an insect in the ear and for dust in the eye.', 'A foreign body is anything that enters the body where it does not belong. Insect in the ear: pour a little clean cooking oil or warm water to float it out, then see a health worker if it remains. Dust in the eye: do not rub; wash it out with clean water, or lift the upper eyelid over the lower one.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T10', true),
  ('P6_SCI_T10-Q18', 'P6', 'Science', 'Accidents and First Aid', 158, 'What should be done for a child who has swallowed paraffin, and what must never be done?', 'The child should be taken to hospital immediately, carrying the container if possible, and kept calm and on their side. Never make the child vomit, because paraffin coming back up can enter the lungs and cause serious damage.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T10', true),
  ('P6_SCI_T10-Q19', 'P6', 'Science', 'Accidents and First Aid', 159, 'Give the first aid for a person choking on food.', 'Encourage the person to cough; bend a child forward and give firm back blows between the shoulder blades; keep checking the mouth and remove anything you can see easily; call for help at once if the object does not come out.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T10', true),
  ('P6_SCI_T10-Q20', 'P6', 'Science', 'Accidents and First Aid', 160, 'Why should a person who has nearly drowned be taken to hospital even if they look well?', 'Because water that entered the lungs can cause breathing problems and infection several hours later, so the person must be checked by a health worker even if they seem to have recovered.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T10', true),
  ('P6_SCI_T11-Q1', 'P6', 'Science', 'Sanitation', 161, 'What is sanitation?', 'Sanitation is keeping the surroundings clean and disposing of human waste and rubbish safely so that people stay healthy.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T11', true),
  ('P6_SCI_T11-Q2', 'P6', 'Science', 'Sanitation', 162, 'Name any five diseases caused by poor sanitation.', 'Any five of: cholera, typhoid, dysentery, diarrhoea, worms, bilharzia, hepatitis, jiggers.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T11', true),
  ('P6_SCI_T11-Q3', 'P6', 'Science', 'Sanitation', 163, 'Give the full meaning of VIP latrine.', 'Ventilated Improved Pit latrine.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T11', true),
  ('P6_SCI_T11-Q4', 'P6', 'Science', 'Sanitation', 164, 'Name three special features of a VIP latrine and explain how it removes smell.', 'Features: a vent pipe from the pit to above the roof, a fly screen at the top of the pipe, and a dark interior with an uncovered squat hole. The sun heats the vent pipe so the air inside rises and carries the smell out, while fresh air enters through the door.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T11', true),
  ('P6_SCI_T11-Q5', 'P6', 'Science', 'Sanitation', 165, 'How does a VIP latrine control flies?', 'Flies in the dark pit fly towards the light at the top of the vent pipe and are trapped by the fly screen, where they die.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T11', true),
  ('P6_SCI_T11-Q6', 'P6', 'Science', 'Sanitation', 166, 'Give one advantage and one disadvantage of an ordinary pit latrine.', 'Advantage: it is cheap and easy to build with local materials and needs no water. Disadvantage: it smells and attracts flies (it also fills up and must be replaced).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T11', true),
  ('P6_SCI_T11-Q7', 'P6', 'Science', 'Sanitation', 167, 'What is an Ecosan toilet, and what is added after each use?', 'An Ecosan (ecological sanitation) toilet is one that separates urine from faeces and turns the waste into manure. Ash or dry soil is added after each use.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T11', true),
  ('P6_SCI_T11-Q8', 'P6', 'Science', 'Sanitation', 168, 'Give any three advantages of an Ecosan toilet.', 'Any three of: it provides manure; it suits rocky, sandy, waterlogged or crowded areas; it does not pollute ground water; there is no smell when ash is used; no deep pit has to be dug.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T11', true),
  ('P6_SCI_T11-Q9', 'P6', 'Science', 'Sanitation', 169, 'In what kind of areas is an Ecosan toilet especially useful, and why?', 'In rocky, sandy, waterlogged or very crowded areas, because a deep pit cannot be dug safely there and a pit would collapse or pollute the ground water.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T11', true),
  ('P6_SCI_T11-Q10', 'P6', 'Science', 'Sanitation', 170, 'What is a potty, and how should it be used and cleaned?', 'A potty is a small portable container used by babies and small children who cannot use the latrine. It must be emptied into the latrine immediately, washed with clean water and soap, and dried in the sun — never emptied in the compound.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T11', true),
  ('P6_SCI_T11-Q11', 'P6', 'Science', 'Sanitation', 171, 'What is a water closet? Give two advantages and two disadvantages.', 'A water closet is a flush toilet with a cistern and a water seal that carries waste to a septic tank or sewer. Advantages: it is clean and has no smell; it is comfortable and free from flies. Disadvantages: it needs plenty of piped water; it is expensive and blocks easily.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T11', true),
  ('P6_SCI_T11-Q12', 'P6', 'Science', 'Sanitation', 172, 'Give any six importances of using a toilet or latrine.', 'Any six of: it prevents diseases such as cholera and worms; it keeps the compound and gardens free of human waste; it controls flies and bad smells; it protects water sources; it gives privacy and dignity; it keeps the home clean; it is required by public health law.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T11', true),
  ('P6_SCI_T11-Q13', 'P6', 'Science', 'Sanitation', 173, 'Explain how disease travels from faeces to the mouth, and how using a latrine breaks the path.', 'Faeces left in the open are carried to food and the mouth by flies, fingers, food, fluids and fields — the "five Fs". Using a latrine keeps the faeces sealed in a pit so flies and feet cannot carry them, and washing hands with soap removes what is on the fingers, so the path is broken.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T11', true),
  ('P6_SCI_T11-Q14', 'P6', 'Science', 'Sanitation', 174, 'Give any six rules for the proper use of a latrine.', 'Any six of: use the latrine every time; aim into the hole and keep the slab clean; cover the hole after use in an ordinary latrine; put used paper in the pit; add ash in an Ecosan toilet; flush a water closet; wash hands with soap afterwards; teach children to use the potty properly.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T11', true),
  ('P6_SCI_T11-Q15', 'P6', 'Science', 'Sanitation', 175, 'Give any six ways of maintaining a latrine.', 'Any six of: sweep and scrub the floor and slab daily; use water or disinfectant; keep soap and water at the door; repair cracks, doors and roofs; keep the vent screen in good order; keep the door closed; do not throw rubbish into the pit; plant grass around it; dig a new pit when it is nearly full.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T11', true),
  ('P6_SCI_T11-Q16', 'P6', 'Science', 'Sanitation', 176, 'Why should rubbish and polythene never be thrown into a pit latrine?', 'Because they do not rot, so they fill the pit quickly and shorten its life, and in a flush toilet they cause blockages.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T11', true),
  ('P6_SCI_T11-Q17', 'P6', 'Science', 'Sanitation', 177, 'Where should a latrine be sited in relation to a water source and the house?', 'At least 30 metres from a water source and downhill from it, and about 6 metres from the house, downwind, on firm well-drained ground.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T11', true),
  ('P6_SCI_T11-Q18', 'P6', 'Science', 'Sanitation', 178, 'Give the difference between a VIP latrine and an ordinary pit latrine in the way the squat hole is treated.', 'In a VIP latrine the squat hole is left uncovered so that air can flow through the pit and up the vent pipe; in an ordinary pit latrine the hole is covered after use to keep out flies and reduce the smell.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T11', true),
  ('P6_SCI_T11-Q19', 'P6', 'Science', 'Sanitation', 179, 'Why should hands be washed with soap after using a latrine?', 'Because germs from faeces remain on the fingers, and hands touch food, water and other people. Washing with soap removes those germs and prevents diseases such as diarrhoea, cholera and worms.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T11', true),
  ('P6_SCI_T11-Q20', 'P6', 'Science', 'Sanitation', 180, 'What should be done when a pit latrine is nearly full?', 'It should be closed and covered with soil and a new pit dug elsewhere; the slab can be moved to the new pit, and the old site should be marked and, in time, planted with trees.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T11', true),
  ('P6_SCI_T12-Q1', 'P6', 'Science', 'The Reproductive System', 181, 'Give the difference between growth and development.', 'Growth is an increase in the size and weight of the body, while development is the change that makes the body able to do more, such as walking, talking and reproducing.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T12', true),
  ('P6_SCI_T12-Q2', 'P6', 'Science', 'The Reproductive System', 182, 'What is puberty, and at about what age does it begin in girls and in boys?', 'Puberty is the stage at which the reproductive organs become mature and a young person becomes able to produce children. It begins at about 10–14 years in girls and 12–16 years in boys.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T12', true),
  ('P6_SCI_T12-Q3', 'P6', 'Science', 'The Reproductive System', 183, 'What is adolescence?', 'Adolescence is the period of change between childhood and adulthood, affecting the body, the mind and the feelings.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T12', true),
  ('P6_SCI_T12-Q4', 'P6', 'Science', 'The Reproductive System', 184, 'Give any four physical changes at puberty in girls and four in boys.', 'Girls: breasts develop; hips widen; menstruation begins; pubic and armpit hair grows (also oily skin, rapid growth). Boys: the voice deepens; the chest and shoulders broaden; wet dreams begin; facial, pubic and armpit hair grows.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T12', true),
  ('P6_SCI_T12-Q5', 'P6', 'Science', 'The Reproductive System', 185, 'Give any four social and emotional changes during adolescence.', 'Any four of: wanting independence; strong peer influence; quick changes of mood; shyness; interest in the opposite sex; wanting privacy; new interest in appearance.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T12', true),
  ('P6_SCI_T12-Q6', 'P6', 'Science', 'The Reproductive System', 186, 'Give the difference between primary and secondary sex characteristics, with two examples of each.', 'Primary characteristics are the reproductive organs present at birth, for example the testes and the ovaries. Secondary characteristics appear at puberty, for example breasts in girls and a deep voice in boys.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T12', true),
  ('P6_SCI_T12-Q7', 'P6', 'Science', 'The Reproductive System', 187, 'Name any four parts of the male reproductive system and the work of each.', 'Any four: testes — produce sperm cells; scrotum — holds the testes and keeps them cool; sperm duct — carries sperms; urethra — passes semen and urine out; penis — the organ through which semen and urine leave the body.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T12', true),
  ('P6_SCI_T12-Q8', 'P6', 'Science', 'The Reproductive System', 188, 'Name any four parts of the female reproductive system and the work of each.', 'Any four: ovaries — produce egg cells; fallopian tubes — carry the egg and are where fertilisation happens; uterus — where the baby develops; cervix — the neck of the uterus; vagina — the passage to the outside.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T12', true),
  ('P6_SCI_T12-Q9', 'P6', 'Science', 'The Reproductive System', 189, 'Where are sperm cells produced, and where are egg cells produced?', 'Sperm cells are produced in the testes; egg cells are produced in the ovaries.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T12', true),
  ('P6_SCI_T12-Q10', 'P6', 'Science', 'The Reproductive System', 190, 'What is menstruation, and about how long is the menstrual cycle?', 'Menstruation is the monthly flow of blood and the lining of the uterus through the vagina when the egg has not been fertilised. The cycle is about 28 days.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T12', true),
  ('P6_SCI_T12-Q11', 'P6', 'Science', 'The Reproductive System', 191, 'What is fertilisation, and where does it take place?', 'Fertilisation is the joining of a sperm cell and an egg cell. It takes place in the fallopian tube (oviduct).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T12', true),
  ('P6_SCI_T12-Q12', 'P6', 'Science', 'The Reproductive System', 192, 'Give the meaning of conception, zygote and gestation.', 'Conception — the fertilised egg attaching to the wall of the uterus and beginning to grow; zygote — the single cell formed at fertilisation; gestation — the period the baby develops in the womb.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T12', true),
  ('P6_SCI_T12-Q13', 'P6', 'Science', 'The Reproductive System', 193, 'How long does pregnancy last, and what is the work of the placenta?', 'Pregnancy lasts about nine months (40 weeks). The placenta supplies the baby with food and oxygen from the mother and carries away its waste.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T12', true),
  ('P6_SCI_T12-Q14', 'P6', 'Science', 'The Reproductive System', 194, 'Give any four signs of pregnancy.', 'Any four of: the monthly periods stop; morning sickness; the breasts enlarge; the abdomen grows; tiredness; changes in appetite.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T12', true),
  ('P6_SCI_T12-Q15', 'P6', 'Science', 'The Reproductive System', 195, 'Give any six ways of caring for a pregnant mother.', 'Any six of: attend antenatal clinic early and regularly; eat a balanced diet rich in iron; take the supplements given; sleep under a treated mosquito net; rest and avoid heavy work; avoid alcohol, smoking and self-medication; keep clean; deliver at a health centre with a trained health worker.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T12', true),
  ('P6_SCI_T12-Q16', 'P6', 'Science', 'The Reproductive System', 196, 'Give any four problems that can occur during pregnancy.', 'Any four of: anaemia, malaria, high blood pressure, miscarriage, bleeding, excessive vomiting, obstructed labour, malnutrition, infections including HIV.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T12', true),
  ('P6_SCI_T12-Q17', 'P6', 'Science', 'The Reproductive System', 197, 'Give any five effects of teenage pregnancy and four ways of preventing it.', 'Effects (any five): danger to the health and life of the girl and baby; obstructed labour and fistula; low birth weight; dropping out of school; poverty; stigma and rejection; unsafe abortion. Prevention (any four): stay in school; abstain from sex; avoid bad company, alcohol and drugs; refuse gifts and lifts from older people; report abuse to a trusted adult; get correct information from parents and health workers.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T12', true),
  ('P6_SCI_T12-Q18', 'P6', 'Science', 'The Reproductive System', 198, 'Give any six ways of caring for the reproductive organs.', 'Any six of: bathe daily and wash the private parts with clean water; wear clean cotton underwear and change it daily; wipe from front to back; use and change clean sanitary materials; never insert anything into the private parts; avoid harmful traditional practices; treat itching or discharge early; abstain from sex; report anybody who touches you wrongly.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T12', true),
  ('P6_SCI_T12-Q19', 'P6', 'Science', 'The Reproductive System', 199, 'What is family planning? Give any five reasons why it is important.', 'Family planning is deciding how many children to have and when to have them, using acceptable methods. Importance (any five): it protects the mother''s health; it gives each child better care and education; it reduces infant and maternal deaths; it helps the family plan its money; it slows very rapid population growth; it allows parents to work and rest.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T12', true),
  ('P6_SCI_T12-Q20', 'P6', 'Science', 'The Reproductive System', 200, 'Name three natural and three artificial methods of family planning, and correct any two myths about family planning.', 'Natural: abstinence, the calendar (rhythm) method, breastfeeding in the early months. Artificial: condoms, pills, injections (also implants, the loop). Myths corrected: "family planning makes a woman permanently barren" — most methods are reversible and fertility returns when they are stopped; "it is only for women" — it is the responsibility of both partners.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P6_SCI_T12', true),
  ('P7_SCI_T01-Q1', 'P7', 'Science', 'The Muscular–skeletal System', 1, 'What is a skeleton?', 'A skeleton is the framework of bones that supports the body and gives it shape.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T01', true),
  ('P7_SCI_T01-Q2', 'P7', 'Science', 'The Muscular–skeletal System', 2, 'Name the two main parts of the human skeleton.', 'The axial skeleton and the appendicular skeleton.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T01', true),
  ('P7_SCI_T01-Q3', 'P7', 'Science', 'The Muscular–skeletal System', 3, 'Name any four bones found in the arm and hand.', 'Any four of: humerus, radius, ulna, carpals, metacarpals, phalanges.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T01', true),
  ('P7_SCI_T01-Q4', 'P7', 'Science', 'The Muscular–skeletal System', 4, 'Name the longest bone and the smallest bone in the human body.', 'Longest — the femur; smallest — the stapes in the middle ear.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T01', true),
  ('P7_SCI_T01-Q5', 'P7', 'Science', 'The Muscular–skeletal System', 5, 'Give the three types of joints according to movement, with one example of each.', 'Immovable — joints of the cranium; slightly movable — joints between the vertebrae; freely movable — the shoulder joint.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T01', true),
  ('P7_SCI_T01-Q6', 'P7', 'Science', 'The Muscular–skeletal System', 6, 'Name the four types of freely movable joints.', 'Ball and socket, hinge, pivot and gliding.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T01', true),
  ('P7_SCI_T01-Q7', 'P7', 'Science', 'The Muscular–skeletal System', 7, 'Give the difference between a ligament and a tendon.', 'A ligament joins bone to bone, while a tendon joins muscle to bone.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T01', true),
  ('P7_SCI_T01-Q8', 'P7', 'Science', 'The Muscular–skeletal System', 8, 'Differentiate between voluntary and involuntary muscles.', 'Voluntary muscles are under our control, for example the arm muscles; involuntary muscles work on their own, for example the muscles of the stomach.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T01', true),
  ('P7_SCI_T01-Q9', 'P7', 'Science', 'The Muscular–skeletal System', 9, 'Which muscles work together to bend and straighten the arm?', 'The biceps and the triceps. The biceps contracts to bend the arm, and the triceps contracts to straighten it.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T01', true),
  ('P7_SCI_T01-Q10', 'P7', 'Science', 'The Muscular–skeletal System', 10, 'State any four functions of the muscular–skeletal system.', 'Any four of: support, giving shape, protection of organs, movement, production of blood cells, storage of minerals, attachment of muscles.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T01', true),
  ('P7_SCI_T01-Q11', 'P7', 'Science', 'The Muscular–skeletal System', 11, 'Name the disease caused by lack of vitamin D and calcium in children and give one sign.', 'Rickets — the child has bent (bowed) legs and soft, weak bones.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T01', true),
  ('P7_SCI_T01-Q12', 'P7', 'Science', 'The Muscular–skeletal System', 12, 'Name the four types of fractures.', 'Simple (closed), compound (open), greenstick and comminuted.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T01', true),
  ('P7_SCI_T01-Q13', 'P7', 'Science', 'The Muscular–skeletal System', 13, 'Give the first aid you would give to a person with a fractured arm.', 'Keep the person calm and still, do not try to push the bone back, support the arm with a splint and a sling, control any bleeding, and take the person to a health worker immediately.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T01', true),
  ('P7_SCI_T01-Q14', 'P7', 'Science', 'The Muscular–skeletal System', 14, 'Give three ways of keeping the muscular–skeletal system healthy.', 'Any three of: eat a balanced diet rich in calcium and protein, get vitamin D from morning sunshine, exercise regularly, rest enough, avoid accidents, immunise against polio, keep correct posture.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T01', true),
  ('P7_SCI_T01-Q15', 'P7', 'Science', 'The Muscular–skeletal System', 15, 'State any three importances of correct posture.', 'Any three of: it keeps the backbone straight, it prevents back and neck pain, it allows the lungs to work properly, it prevents deformities, it makes a person look smart.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T01', true),
  ('P7_SCI_T02-Q1', 'P7', 'Science', 'Electricity and Magnetism', 16, 'Define electricity and name its two types.', 'Electricity is a form of energy caused by the movement of electrons. Its two types are static electricity and current electricity.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T02', true),
  ('P7_SCI_T02-Q2', 'P7', 'Science', 'Electricity and Magnetism', 17, 'Give any four sources of electricity used in Uganda.', 'Any four of: dry cells, hydro-electric power, solar panels, wind, generators, geothermal, thermal (fossil fuels), biogas.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T02', true),
  ('P7_SCI_T02-Q3', 'P7', 'Science', 'Electricity and Magnetism', 18, 'Give the difference between a conductor and an insulator, with one example of each.', 'A conductor allows electricity to pass through it, for example copper; an insulator does not, for example rubber.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T02', true),
  ('P7_SCI_T02-Q4', 'P7', 'Science', 'Electricity and Magnetism', 19, 'Draw and label a simple electric circuit. (Cell, switch, bulb and connecting wires.)', 'Learner''s drawing. It should show a cell, connecting wires, a switch and a bulb forming a complete (closed) loop.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T02', true),
  ('P7_SCI_T02-Q5', 'P7', 'Science', 'Electricity and Magnetism', 20, 'Give two differences between a series circuit and a parallel circuit.', 'In a series circuit the bulbs are in one path, so if one blows all go off and the bulbs are dimmer. In a parallel circuit each bulb is on its own branch, so if one blows the others stay on and the bulbs are brighter.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T02', true),
  ('P7_SCI_T02-Q6', 'P7', 'Science', 'Electricity and Magnetism', 21, 'What is a short circuit, and give two of its causes?', 'A short circuit is when current finds a shorter path of very little resistance and flows without passing through the appliance. Causes: worn out or bare wires touching, water reaching the wires, overloading a socket, poor wiring.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T02', true),
  ('P7_SCI_T02-Q7', 'P7', 'Science', 'Electricity and Magnetism', 22, 'State any four safety precautions in handling electricity.', 'Any four of: never touch switches with wet hands; do not put metal objects in sockets; do not overload sockets; replace worn out wires; switch off the mains before repairs; keep children away from sockets; never touch fallen power lines.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T02', true),
  ('P7_SCI_T02-Q8', 'P7', 'Science', 'Electricity and Magnetism', 23, 'Give any four uses of electricity in a home.', 'Any four of: lighting, cooking, ironing, refrigeration, pumping water, running radios and televisions, charging phones, running computers.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T02', true),
  ('P7_SCI_T02-Q9', 'P7', 'Science', 'Electricity and Magnetism', 24, 'Name any four magnetic materials.', 'Iron, steel, nickel and cobalt.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T02', true),
  ('P7_SCI_T02-Q10', 'P7', 'Science', 'Electricity and Magnetism', 25, 'Give the difference between natural and artificial magnets, with one example of each.', 'Natural magnets are found in the ground, for example lodestone; artificial magnets are made by people, for example a bar magnet.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T02', true),
  ('P7_SCI_T02-Q11', 'P7', 'Science', 'Electricity and Magnetism', 26, 'State the law of magnetism.', 'Like poles repel and unlike poles attract.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T02', true),
  ('P7_SCI_T02-Q12', 'P7', 'Science', 'Electricity and Magnetism', 27, 'Describe how you would make a magnet by the stroking method.', 'Place the steel bar on a table. Take one pole of a strong magnet and stroke the bar from one end to the other, always in the same direction, lifting the magnet high at the end of each stroke. Repeat many times; the bar becomes a magnet.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T02', true),
  ('P7_SCI_T02-Q13', 'P7', 'Science', 'Electricity and Magnetism', 28, 'Give three ways in which a magnet can lose its magnetism.', 'Any three of: heating it strongly, hammering or dropping it repeatedly, passing alternating current through it, storing it carelessly.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T02', true),
  ('P7_SCI_T02-Q14', 'P7', 'Science', 'Electricity and Magnetism', 29, 'How are magnets properly stored?', 'Bar magnets are stored in pairs with unlike poles facing each other and soft iron keepers placed across the ends.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T02', true),
  ('P7_SCI_T02-Q15', 'P7', 'Science', 'Electricity and Magnetism', 30, 'Explain briefly how an electric bell works.', 'When the switch is pressed, current flows through the electromagnet, which attracts the soft iron armature so that the hammer hits the gong. This movement breaks the circuit, the electromagnet loses its magnetism and the spring pulls the armature back, closing the circuit again. The action repeats quickly, so the bell rings continuously.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T02', true),
  ('P7_SCI_T03-Q1', 'P7', 'Science', 'Energy Resources in the Environment', 31, 'Define energy and name any four forms of energy.', 'Energy is the ability to do work. Forms: heat, light, sound, electrical, chemical, mechanical (any four).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T03', true),
  ('P7_SCI_T03-Q2', 'P7', 'Science', 'Energy Resources in the Environment', 32, 'What is the main source of energy on earth?', 'The sun.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T03', true),
  ('P7_SCI_T03-Q3', 'P7', 'Science', 'Energy Resources in the Environment', 33, 'Name three energy resources obtained from water.', 'Hydro-electric power, steam energy and tidal energy.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T03', true),
  ('P7_SCI_T03-Q4', 'P7', 'Science', 'Energy Resources in the Environment', 34, 'Name the three fossil fuels.', 'Coal, petroleum (crude oil) and natural gas.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T03', true),
  ('P7_SCI_T03-Q5', 'P7', 'Science', 'Energy Resources in the Environment', 35, 'Give two disadvantages of using fossil fuels.', 'They pollute the air and cause global warming; they are non-renewable and will get used up. (Also: mining and drilling damage the environment.)', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T03', true),
  ('P7_SCI_T03-Q6', 'P7', 'Science', 'Energy Resources in the Environment', 36, 'Name two energy resources obtained from plants.', 'Any two of: firewood, charcoal, biofuel (ethanol or biodiesel), biogas from plant waste, crop residues such as bagasse.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T03', true),
  ('P7_SCI_T03-Q7', 'P7', 'Science', 'Energy Resources in the Environment', 37, 'What is biogas and how is it made?', 'Biogas is a gas produced when animal dung or other organic waste rots in a digester without air. The gas is piped away and burnt for cooking and lighting.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T03', true),
  ('P7_SCI_T03-Q8', 'P7', 'Science', 'Energy Resources in the Environment', 38, 'Give three advantages of using biogas.', 'Any three of: it is cheap and renewable; it uses waste; the slurry left over is good manure; it reduces the cutting of trees; it burns cleanly without smoke.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T03', true),
  ('P7_SCI_T03-Q9', 'P7', 'Science', 'Energy Resources in the Environment', 39, 'Give two ways in which animals provide energy.', 'Animals give muscle energy — oxen ploughing, donkeys carrying loads — and their dung is used to make biogas.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T03', true),
  ('P7_SCI_T03-Q10', 'P7', 'Science', 'Energy Resources in the Environment', 40, 'Give the difference between renewable and non-renewable energy resources.', 'Renewable resources can be replaced or never run out, such as solar and wind; non-renewable resources get used up and cannot be replaced, such as coal and oil.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T03', true),
  ('P7_SCI_T03-Q11', 'P7', 'Science', 'Energy Resources in the Environment', 41, 'Classify these as renewable or non-renewable: solar, coal, wind, natural gas.', 'Renewable: solar, wind. Non-renewable: coal, natural gas.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T03', true),
  ('P7_SCI_T03-Q12', 'P7', 'Science', 'Energy Resources in the Environment', 42, 'Name three hydro-electric power stations in Uganda.', 'Any three of: Nalubaale, Kiira, Bujagali, Isimba, Karuma.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T03', true),
  ('P7_SCI_T03-Q13', 'P7', 'Science', 'Energy Resources in the Environment', 43, 'Give two advantages and two disadvantages of hydro-electric power.', 'Advantages: it is renewable and it does not pollute the air (also cheap to run, and the dam stores water). Disadvantages: dams are very expensive to build and they may flood people''s land (also affected by drought).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T03', true),
  ('P7_SCI_T03-Q14', 'P7', 'Science', 'Energy Resources in the Environment', 44, 'State any four importances of energy resources.', 'Any four of: cooking and lighting, running industries, transport, pumping water, powering hospitals and schools, communication, creating jobs, farm work.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T03', true),
  ('P7_SCI_T03-Q15', 'P7', 'Science', 'Energy Resources in the Environment', 45, 'Suggest four ways of conserving energy in your home or school.', 'Any four of: switch off lights and appliances not in use; use energy-saving bulbs and stoves; use solar or biogas instead of firewood; plant trees for firewood; cover pots while cooking; service vehicles regularly; walk or share transport for short journeys.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T03', true),
  ('P7_SCI_T04-Q1', 'P7', 'Science', 'Simple Machines and Friction', 46, 'What is a simple machine? Give two ways in which machines make work easier.', 'A simple machine is a device that makes work easier. It allows a small effort to move a big load, and it can change the direction of the force applied.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T04', true),
  ('P7_SCI_T04-Q2', 'P7', 'Science', 'Simple Machines and Friction', 47, 'Define effort, load and fulcrum.', 'Effort is the force applied to the machine; load is the weight or resistance the machine works against; fulcrum is the fixed point about which a lever turns.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T04', true),
  ('P7_SCI_T04-Q3', 'P7', 'Science', 'Simple Machines and Friction', 48, 'A load of 800 N is lifted by an effort of 200 N. Find the mechanical advantage.', 'M.A. = 800 ÷ 200 = 4', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T04', true),
  ('P7_SCI_T04-Q4', 'P7', 'Science', 'Simple Machines and Friction', 49, 'A machine has a mechanical advantage of 6. What effort is needed to lift a load of 540 N?', 'Effort = 540 ÷ 6 = 90 N', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T04', true),
  ('P7_SCI_T04-Q5', 'P7', 'Science', 'Simple Machines and Friction', 50, 'State the principle of moments.', 'Load × distance of the load from the fulcrum = effort × distance of the effort from the fulcrum.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T04', true),
  ('P7_SCI_T04-Q6', 'P7', 'Science', 'Simple Machines and Friction', 51, 'A load of 50 N is 3 m from the fulcrum. Find the effort acting 5 m from the fulcrum on the other side.', '50 × 3 = E × 5 → 150 = 5E → E = 30 N', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T04', true),
  ('P7_SCI_T04-Q7', 'P7', 'Science', 'Simple Machines and Friction', 52, 'Name the three classes of levers and give one example of each.', 'First class — see-saw or scissors; second class — wheelbarrow; third class — fishing rod.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T04', true),
  ('P7_SCI_T04-Q8', 'P7', 'Science', 'Simple Machines and Friction', 53, 'Name the class of lever to which a pair of pliers belongs.', 'First class (the fulcrum is between the effort and the load).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T04', true),
  ('P7_SCI_T04-Q9', 'P7', 'Science', 'Simple Machines and Friction', 54, 'What is an inclined plane, and give two examples?', 'An inclined plane is a slanting surface used to raise a load. Examples: a ramp and a plank used to roll a drum onto a lorry (also staircases and zigzag hill roads).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T04', true),
  ('P7_SCI_T04-Q10', 'P7', 'Science', 'Simple Machines and Friction', 55, 'Give two examples each of a wedge and a screw.', 'Wedge: axe, knife (also panga, nail, chisel). Screw: bolt and nut, screw jack (also vice, corkscrew).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T04', true),
  ('P7_SCI_T04-Q11', 'P7', 'Science', 'Simple Machines and Friction', 56, 'Give the difference between a fixed pulley and a movable pulley.', 'A fixed pulley only changes the direction of the force, so the effort equals the load; a movable pulley reduces the effort needed, giving a mechanical advantage of about 2.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T04', true),
  ('P7_SCI_T04-Q12', 'P7', 'Science', 'Simple Machines and Friction', 57, 'Give three examples of a wheel and axle.', 'Any three of: steering wheel, door knob, bicycle wheel and pedals, windlass on a well, tap handle, screwdriver.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T04', true),
  ('P7_SCI_T04-Q13', 'P7', 'Science', 'Simple Machines and Friction', 58, 'Define friction and give three examples of friction in daily life.', 'Friction is the force that opposes movement between two surfaces in contact. Examples: brakes stopping a bicycle; shoes gripping the ground when walking; a match lighting when struck.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T04', true),
  ('P7_SCI_T04-Q14', 'P7', 'Science', 'Simple Machines and Friction', 59, 'Give three ways of increasing friction and three ways of reducing it.', 'Increase: make surfaces rougher; put treads on tyres and shoes; press the surfaces together more firmly. Reduce: lubricate with oil or grease; use ball bearings or rollers; polish surfaces or streamline the shape.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T04', true),
  ('P7_SCI_T04-Q15', 'P7', 'Science', 'Simple Machines and Friction', 60, 'Give two disadvantages of friction.', 'It wears out tyres, shoes and machine parts, and it wastes energy as heat, so machines use more fuel. (It also causes noise and overheating.)', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T04', true),
  ('P7_SCI_T05-Q1', 'P7', 'Science', 'The Excretory System', 61, 'Define excretion and give the difference between excretion and egestion.', 'Excretion is the removal of waste products made inside the body. Egestion is the removal of undigested food (faeces), which was never part of the body''s chemical processes.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T05', true),
  ('P7_SCI_T05-Q2', 'P7', 'Science', 'The Excretory System', 62, 'Name the four excretory organs and the waste each one removes.', 'Skin — sweat; kidneys — urine; lungs — carbon dioxide and water vapour; liver — bile pigments (and it makes urea).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T05', true),
  ('P7_SCI_T05-Q3', 'P7', 'Science', 'The Excretory System', 63, 'Name the two main layers of the human skin.', 'The epidermis and the dermis.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T05', true),
  ('P7_SCI_T05-Q4', 'P7', 'Science', 'The Excretory System', 64, 'Name any four parts found in the dermis.', 'Any four of: sweat glands, sebaceous glands, hair follicles, blood vessels, nerve endings, fatty layer.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T05', true),
  ('P7_SCI_T05-Q5', 'P7', 'Science', 'The Excretory System', 65, 'State any four functions of the skin.', 'Any four of: excretion of sweat, control of body temperature, protection against germs and injury, sensation, formation of vitamin D, storage of fat and water.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T05', true),
  ('P7_SCI_T05-Q6', 'P7', 'Science', 'The Excretory System', 66, 'Name any three skin diseases and the cause of each.', 'Any three, for example: scabies — mites; ringworm — a fungus; boils — bacteria; athlete''s foot — a fungus; eczema — allergy or irritation.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T05', true),
  ('P7_SCI_T05-Q7', 'P7', 'Science', 'The Excretory System', 67, 'Give four ways of caring for the skin.', 'Any four of: bathe daily with soap and clean water; wear clean clothes; cut nails short; treat wounds early; eat a balanced diet and drink water; avoid sharing towels and combs; wear shoes.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T05', true),
  ('P7_SCI_T05-Q8', 'P7', 'Science', 'The Excretory System', 68, 'Name the four parts of the urinary system in the order urine passes through them.', 'Kidneys → ureters → urinary bladder → urethra.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T05', true),
  ('P7_SCI_T05-Q9', 'P7', 'Science', 'The Excretory System', 69, 'Name any three parts of a kidney.', 'Any three of: cortex, medulla, pelvis, nephrons, renal artery, renal vein.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T05', true),
  ('P7_SCI_T05-Q10', 'P7', 'Science', 'The Excretory System', 70, 'State any three functions of the kidney.', 'Any three of: filtering the blood, removing urea and excess salts, forming urine, controlling the amount of water in the body.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T05', true),
  ('P7_SCI_T05-Q11', 'P7', 'Science', 'The Excretory System', 71, 'Name any three diseases or disorders of the kidney.', 'Any three of: kidney stones, nephritis, kidney failure, bilharzia, cystitis.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T05', true),
  ('P7_SCI_T05-Q12', 'P7', 'Science', 'The Excretory System', 72, 'How is kidney failure treated?', 'By dialysis — cleaning the blood using a machine — or by a kidney transplant.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T05', true),
  ('P7_SCI_T05-Q13', 'P7', 'Science', 'The Excretory System', 73, 'Which two wastes do the lungs remove?', 'Carbon dioxide and water vapour.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T05', true),
  ('P7_SCI_T05-Q14', 'P7', 'Science', 'The Excretory System', 74, 'Name any three diseases of the lungs and give one way of preventing lung disease.', 'Any three of: tuberculosis, pneumonia, bronchitis, asthma, lung cancer, whooping cough. Prevention: do not smoke, keep rooms well ventilated, avoid smoke and dust, and immunise children.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T05', true),
  ('P7_SCI_T05-Q15', 'P7', 'Science', 'The Excretory System', 75, 'Give any four good habits that keep the excretory system working well.', 'Any four of: drink plenty of clean water; eat a balanced diet with little salt; bathe daily; exercise regularly; avoid alcohol, smoking and drug abuse; do not hold urine too long; go for medical check-ups.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T05', true),
  ('P7_SCI_T06-Q1', 'P7', 'Science', 'Light Energy', 76, 'Define light and give two natural and two artificial sources of light.', 'Light is a form of energy that enables us to see. Natural: the sun, lightning (also stars, fireflies). Artificial: electric bulb, candle (also torch, lantern).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T06', true),
  ('P7_SCI_T06-Q2', 'P7', 'Science', 'Light Energy', 77, 'Give the difference between a luminous and a non-luminous body.', 'A luminous body produces its own light, for example the sun; a non-luminous body does not produce light but is seen when light falls on it, for example the moon.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T06', true),
  ('P7_SCI_T06-Q3', 'P7', 'Science', 'Light Energy', 78, 'How does light travel? Describe one experiment that proves it.', 'Light travels in straight lines. Take three cards with holes punched at the same height, line them up with a candle behind them; the candle is seen only when the three holes are in a straight line. When one card is moved, the light is blocked.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T06', true),
  ('P7_SCI_T06-Q4', 'P7', 'Science', 'Light Energy', 79, 'Give the difference between transparent, translucent and opaque materials, with one example of each.', 'Transparent lets nearly all light through (clear glass); translucent lets only some light through (frosted glass or oiled paper); opaque lets no light through (wood).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T06', true),
  ('P7_SCI_T06-Q5', 'P7', 'Science', 'Light Energy', 80, 'What three things are needed for a shadow to form?', 'A source of light, an opaque object and a screen.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T06', true),
  ('P7_SCI_T06-Q6', 'P7', 'Science', 'Light Energy', 81, 'Give the difference between a solar eclipse and a lunar eclipse.', 'In a solar eclipse the moon comes between the sun and the earth. In a lunar eclipse the earth comes between the sun and the moon.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T06', true),
  ('P7_SCI_T06-Q7', 'P7', 'Science', 'Light Energy', 82, 'Describe the image formed by a pin-hole camera.', 'It is real, inverted (upside down), laterally inverted and smaller than the object.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T06', true),
  ('P7_SCI_T06-Q8', 'P7', 'Science', 'Light Energy', 83, 'State the two laws of reflection.', '(i) The angle of incidence is equal to the angle of reflection. (ii) The incident ray, the reflected ray and the normal all lie in the same plane.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T06', true),
  ('P7_SCI_T06-Q9', 'P7', 'Science', 'Light Energy', 84, 'Give four characteristics of an image formed by a plane mirror.', 'It is virtual, upright, the same size as the object, laterally inverted, and as far behind the mirror as the object is in front (any four).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T06', true),
  ('P7_SCI_T06-Q10', 'P7', 'Science', 'Light Energy', 85, 'How does a periscope work?', 'It has two plane mirrors fixed at 45° facing each other. Light from the object strikes the top mirror and is reflected down to the lower mirror, which reflects it into the eye of the observer.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T06', true),
  ('P7_SCI_T06-Q11', 'P7', 'Science', 'Light Energy', 86, 'What is refraction? Give three of its effects.', 'Refraction is the bending of light as it passes from one transparent material to another. Effects: a stick in water looks bent; a pool looks shallower than it is; a coin in water appears raised; dispersion and the rainbow (any three).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T06', true),
  ('P7_SCI_T06-Q12', 'P7', 'Science', 'Light Energy', 87, 'Name the seven colours of white light in order.', 'Red, orange, yellow, green, blue, indigo, violet.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T06', true),
  ('P7_SCI_T06-Q13', 'P7', 'Science', 'Light Energy', 88, 'Name the two types of lenses and give one use of each.', 'Convex (converging) — used in a magnifying glass and cameras; concave (diverging) — used in spectacles for short sight.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T06', true),
  ('P7_SCI_T06-Q14', 'P7', 'Science', 'Light Energy', 89, 'Name any five parts of the human eye and give the work of each.', 'Any five, for example: cornea — lets light in and starts bending it; iris — controls the size of the pupil; pupil — lets light into the eye; lens — focuses light on the retina; retina — where the image is formed; optic nerve — carries the message to the brain.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T06', true),
  ('P7_SCI_T06-Q15', 'P7', 'Science', 'Light Energy', 90, 'Name two eye defects and how each is corrected.', 'Short sight is corrected with concave lenses; long sight is corrected with convex lenses.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T06', true),
  ('P7_SCI_T07-Q1', 'P7', 'Science', 'Interdependence of Things in the Environment', 91, 'Define the environment and name its two components.', 'The environment is everything that surrounds a living thing. Its components are the living (biotic) and the non-living (abiotic).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T07', true),
  ('P7_SCI_T07-Q2', 'P7', 'Science', 'Interdependence of Things in the Environment', 92, 'Give three ways in which animals depend on plants.', 'Any three of: plants give animals food; plants give out oxygen; plants provide shelter and nesting materials; plants provide medicine and shade.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T07', true),
  ('P7_SCI_T07-Q3', 'P7', 'Science', 'Interdependence of Things in the Environment', 93, 'Give three ways in which plants depend on animals.', 'Any three of: animals give out carbon dioxide used in photosynthesis; animal droppings and dead bodies make the soil fertile; animals pollinate flowers; animals disperse seeds; people plant and protect crops; burrowing animals aerate the soil.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T07', true),
  ('P7_SCI_T07-Q4', 'P7', 'Science', 'Interdependence of Things in the Environment', 94, 'Give two ways in which plants depend on other plants.', 'Big trees give shade and shelter to smaller plants; climbing plants use others for support; fallen leaves rot into humus that feeds other plants; legumes add nitrogen to the soil (any two).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T07', true),
  ('P7_SCI_T07-Q5', 'P7', 'Science', 'Interdependence of Things in the Environment', 95, 'Write down a food chain with four members.', 'For example: grass → grasshopper → lizard → hawk.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T07', true),
  ('P7_SCI_T07-Q6', 'P7', 'Science', 'Interdependence of Things in the Environment', 96, 'What is a producer? What is a decomposer?', 'A producer is a green plant that makes its own food. A decomposer is an organism such as bacteria or fungi that rots dead matter and returns nutrients to the soil.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T07', true),
  ('P7_SCI_T07-Q7', 'P7', 'Science', 'Interdependence of Things in the Environment', 97, 'Give the difference between a food chain and a food web.', 'A food chain shows one single path of food energy, while a food web is many food chains joined together, showing that animals feed on more than one thing.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T07', true),
  ('P7_SCI_T07-Q8', 'P7', 'Science', 'Interdependence of Things in the Environment', 98, 'Give three ways in which plants depend on non-living things.', 'Plants use soil for anchorage and mineral salts, water for photosynthesis and transport, air for carbon dioxide, and sunlight as the energy for photosynthesis (any three).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T07', true),
  ('P7_SCI_T07-Q9', 'P7', 'Science', 'Interdependence of Things in the Environment', 99, 'Give two ways in which non-living things benefit from living things.', 'Dead plants and animals add humus and make the soil fertile; plant roots hold the soil and prevent erosion; plants release oxygen and water vapour into the air (any two).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T07', true),
  ('P7_SCI_T07-Q10', 'P7', 'Science', 'Interdependence of Things in the Environment', 100, 'Define agroforestry and name its three types.', 'Agroforestry is the growing of trees together with crops and/or animals on the same piece of land. Types: agri-silviculture, silvo-pastoral and agro-silvo-pastoral.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T07', true),
  ('P7_SCI_T07-Q11', 'P7', 'Science', 'Interdependence of Things in the Environment', 101, 'State any five importances of agroforestry.', 'Any five of: provides firewood, timber and poles; gives shade and windbreaks; leaves make manure; roots control soil erosion; legumes add nitrogen; provides fodder, fruits and medicine; brings extra income; attracts rainfall; uses land productively.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T07', true),
  ('P7_SCI_T07-Q12', 'P7', 'Science', 'Interdependence of Things in the Environment', 102, 'Give three ways of caring for trees on an agroforestry farm.', 'Any three of: watering seedlings, weeding and mulching, pruning branches, fencing against animals, applying manure, controlling pests and diseases, thinning.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T07', true),
  ('P7_SCI_T07-Q13', 'P7', 'Science', 'Interdependence of Things in the Environment', 103, 'Give the difference between pollarding and coppicing.', 'Pollarding is cutting off the top branches and leaving the trunk standing, while coppicing is cutting the whole tree close to the ground so that new shoots grow from the stump.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T07', true),
  ('P7_SCI_T07-Q14', 'P7', 'Science', 'Interdependence of Things in the Environment', 104, 'Outline any five steps in managing a school wood project.', 'Any five of: choose a suitable site; prepare a nursery bed and sow seeds; prepare the land and mark the spacing; transplant at the start of the rains; water and mulch; weed regularly; fence and protect from fire and animals; prune and thin; control pests; keep records; harvest properly and replant.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T07', true),
  ('P7_SCI_T07-Q15', 'P7', 'Science', 'Interdependence of Things in the Environment', 105, 'Give three benefits of a school wood project.', 'Any three of: it supplies firewood and poles for the school; it teaches learners practical skills; it earns the school money; it gives shade and beautifies the compound; it protects the soil and the environment.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T07', true),
  ('P7_SCI_T08-Q1', 'P7', 'Science', 'Population and Health', 106, 'Name any five common sicknesses in a home and give the cause of each.', 'Any five, for example: malaria — a parasite carried by the mosquito; diarrhoea — germs in dirty food and water; typhoid — bacteria in contaminated food or water; worms — worm eggs from dirty hands or bare feet; cough and flu — viruses; scabies — mites.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T08', true),
  ('P7_SCI_T08-Q2', 'P7', 'Science', 'Population and Health', 107, 'How is malaria spread and how can it be prevented at home?', 'Malaria is spread by the bite of an infected female anopheles mosquito. It is prevented by sleeping under a treated mosquito net, draining stagnant water, clearing bushes around the house, closing windows early, and getting tested and treated early.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T08', true),
  ('P7_SCI_T08-Q3', 'P7', 'Science', 'Population and Health', 108, 'Give four ways of controlling common sicknesses in a home.', 'Any four of: keep the home clean; use a latrine and wash hands with soap; boil or treat drinking water; cover food; sleep under a treated net; immunise children; eat a balanced diet; go to a health centre early.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T08', true),
  ('P7_SCI_T08-Q4', 'P7', 'Science', 'Population and Health', 109, 'Name any four health and social problems facing young people today.', 'Any four of: early pregnancy and early marriage, drug and substance abuse, HIV/AIDS and other STIs, defilement and sexual abuse, poor hygiene, child labour, peer pressure, poor nutrition.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T08', true),
  ('P7_SCI_T08-Q5', 'P7', 'Science', 'Population and Health', 110, 'What is anti-social behaviour? Give four examples.', 'Anti-social behaviour is behaviour that harms other people or the community. Examples: stealing, bullying, drug abuse, vandalism, fighting, truancy, gambling (any four).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T08', true),
  ('P7_SCI_T08-Q6', 'P7', 'Science', 'Population and Health', 111, 'Give three effects of drug abuse on a young person.', 'Any three of: poor health and addiction; poor performance and dropping out of school; involvement in crime and accidents; loss of money; broken relationships with family and friends.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T08', true),
  ('P7_SCI_T08-Q7', 'P7', 'Science', 'Population and Health', 112, 'Give three ways of preventing anti-social behaviour among young people.', 'Any three of: guidance and counselling; using free time well in sports and clubs; choosing friends wisely and resisting peer pressure; obeying school and community rules; religious and moral teaching; reporting wrongdoing.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T08', true),
  ('P7_SCI_T08-Q8', 'P7', 'Science', 'Population and Health', 113, 'What should a child do if an adult tries to touch his or her private parts?', 'The child should say NO firmly, get away from the person, and tell a trusted adult at once — a parent, teacher, health worker, religious leader or the police. The child should not keep it secret; it is never the child''s fault.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T08', true),
  ('P7_SCI_T08-Q9', 'P7', 'Science', 'Population and Health', 114, 'What is a health survey? Give four steps followed in carrying one out.', 'A health survey is the collecting of information about the health problems of a community so that they can be solved. Steps: choose the problem; prepare questions or a checklist; get permission from leaders; visit homes and record observations; organise the findings in tables or graphs; report to the community and health workers; suggest and take action (any four).', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T08', true),
  ('P7_SCI_T08-Q10', 'P7', 'Science', 'Population and Health', 115, 'Give three activities, other than a survey, used to address health concerns in a community.', 'Any three of: health education talks and radio programmes; immunisation campaigns; clean-up days; digging latrines and rubbish pits; protecting water sources; distributing mosquito nets; guidance and counselling.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T08', true),
  ('P7_SCI_T08-Q11', 'P7', 'Science', 'Population and Health', 116, 'Define population and census.', 'Population is the total number of people living in a place at a particular time. A census is the official counting of all the people in a country.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T08', true),
  ('P7_SCI_T08-Q12', 'P7', 'Science', 'Population and Health', 117, 'Give three ways of collecting information about the population.', 'Any three of: a national census; birth and death registers; health centre records; school registers; surveys and questionnaires; local council records.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T08', true),
  ('P7_SCI_T08-Q13', 'P7', 'Science', 'Population and Health', 118, 'Give four reasons why a country needs population information.', 'Any four of: to plan for schools, hospitals, water and roads; to know the population growth rate; to plan for food and jobs; to share government services and funds fairly; to plan immunisation and other health services.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T08', true),
  ('P7_SCI_T08-Q14', 'P7', 'Science', 'Population and Health', 119, 'Give four problems caused by a rapidly growing population.', 'Any four of: overcrowding and slums; pressure on schools, hospitals and water; unemployment and poverty; food shortage; land shortage and conflicts; destruction of forests and wetlands; fast spread of disease.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T08', true),
  ('P7_SCI_T08-Q15', 'P7', 'Science', 'Population and Health', 120, 'Name any five activities of a school health club.', 'Any five of: cleaning the compound and latrines; checking personal hygiene; running hand-washing points; making health posters; performing drama, songs and poems; inviting health workers to give talks; growing vegetables and fruit; carrying out health surveys; keeping a first-aid box.', 'smartple-mobile/apps/admin/src/data/revisionBank.json#P7_SCI_T08', true)
insert into public.daily_qa_questions
  (id, grade, subject, topic, sort_order, prompt, answer, options, source_file, is_active)
values
  ('sst-p3-1', 'P3', 'SST', 'Our Sub-County/Division', 1, 'What is a sub-county?', NULL, NULL, 'content/sst_questions_p3_p7.json', true),
  ('sst-p3-2', 'P3', 'SST', 'Our Sub-County/Division', 2, 'Answer in one or two sentences: What is a sub-county?', NULL, NULL, 'content/sst_questions_p3_p7.json', true),
  ('sst-p3-3', 'P3', 'SST', 'Our Sub-County/Division', 3, 'Explain briefly: What is a sub-county?', NULL, NULL, 'content/sst_questions_p3_p7.json', true),
